				cF.flush() cL.flush()
			end
		end
		cF.flush() cL.flush()
	end
	pcall(sliceRuns, true) pcall(sliceRuns, false)
	if not silParts or #silParts > 0 then pcall(silRuns, true) pcall(silRuns, false) end
end
ENT.NEAR = 50   -- studs: things this close to the sketch show their outline, further away = nothing
function ENT.outKind(v, inst)
	local k = v:GetAttribute("DIM_kind")
	if k then return k end
	return inst:IsA("Model") and "extrude" or "cut"
end
-- a block seen from this plane: its outer outline (the 8 corners, flattened, wrapped)
function ENT.boxSilhouette(cf, size, addW, pl)
	local h = size / 2
	local pts = {}
	for _, sx in ipairs({ -1, 1 }) do
		for _, sy in ipairs({ -1, 1 }) do
			for _, sz in ipairs({ -1, 1 }) do pts[#pts + 1] = to2D(pl, (cf * CFrame.new(h.X * sx, h.Y * sy, h.Z * sz)).Position) end
		end
	end
	local hl = ENT.hull2(pts)
	if #hl < 3 then return end
	for i = 1, #hl do addW(toWorld(pl, hl[i]), toWorld(pl, hl[i % #hl + 1]), false, true) end
end
function ENT.ownShape(v, inst, host, hostWhole)
	if not hostWhole then return false end
	if not (inst == host or inst == hostWhole or inst:IsDescendantOf(hostWhole) or hostWhole:IsDescendantOf(inst)) then return false end
	-- v2.40 (Dylan): CUTS in the thing you're sketching on show too (flattened onto the sketch), like its extrudes
	return true
end
-- the projected edge under q
function ENT.refAt(q)
	if not sk or not sk.refLines or not ENT.showEdges then return nil end
	local tol = camDist(W(q)) * 0.02
	local best, bd = nil, tol
	for _, L in ipairs(sk.refLines) do
		local d = ENT.segDist(q, L.a, L.b)
		if d < bd then best, bd = L, d end
	end
	return best
end
-- turn the projected edges into real sketch lines (so you can extrude / cut from a face's outline)
function ENT.edgesToLines()
	if not sk then ENT.err("Open a sketch first.") return end
	local n = 0
	for _, L in ipairs(sk.refLines or {}) do
		table.insert(sk.shapes, { kind = "poly", open = true, pts = { L.a, L.b } })
		n += 1
	end
	if n == 0 then setStatus("No edges to copy here (Edges: ON shows them as light yellow dashes).") return end
	drawSketch() drawPreview() rebuildFields()
	ENT.commitSketch("Edges to lines")
	setStatus("Copied " .. n .. " edge(s) into the sketch as lines. Lines that join up make closed areas you can extrude / cut. Ctrl+Z undoes it.")
end
-- SPLIT: break every drawing at the point on the line nearest the click
-- ===== v2.36 FILLET / CHAMFER: round off or cut off a sketch corner =====
function ENT.filletSize() return tonumber(U.filletR and U.filletR.Text) end
-- the corner nearest q: inside one drawing (rect / polygon / line chain), or where 2 open drawings meet
function ENT.findCorner(q)
	local tol = math.max(0.05, camDist(W(q)) * 0.025)
	local best, bestD = nil, tol
	local ends = {}
	for _, s in ipairs(sk.shapes) do
		if s.kind == "rect" or s.kind == "ngon" or (s.kind == "poly" and not s.spline and not s.axis and s.pts and #s.pts >= 2) then
			local pts = outline(s)
			local n = #pts
			for i = 1, n do
				if (not s.open) or (i > 1 and i < n) then
					local d = (pts[i] - q).Magnitude
					if d < bestD then
						best, bestD = { kind = "inner", s = s, i = i, V = pts[i], P = pts[i - 1] or pts[n], N = pts[i + 1] or pts[1] }, d
					end
				else
					table.insert(ends, { s = s, i = i, V = pts[i], nb = (i == 1) and pts[2] or pts[n - 1] })
				end
			end
		end
	end
	for a = 1, #ends do
		local A = ends[a]
		local d = (A.V - q).Magnitude
		if d < bestD then
			for b = a + 1, #ends do
				local B = ends[b]
				if B.s ~= A.s and (B.V - A.V).Magnitude < 1e-3 then
					best, bestD = { kind = "joint", A = A, B = B, V = A.V, P = A.nb, N = B.nb }, d
					break
				end
			end
		end
	end
	return best
end
-- the new corner points from the P side to the N side (fillet = an arc, chamfer = 2 points)
function ENT.cornerGeom(C, isFillet, r)
	local V = C.V
	local e1, e2 = C.P - V, C.N - V
	local l1, l2 = e1.Magnitude, e2.Magnitude
	if l1 < 1e-4 or l2 < 1e-4 then return nil, "that corner has a zero-length side" end
	local u1, u2 = e1 / l1, e2 / l2
	local th = math.acos(math.clamp(u1:Dot(u2), -1, 1))
	if th < math.rad(1) or th > math.rad(179) then return nil, "not a corner (the lines run straight on)" end
	if not r or r ~= r or r <= 0 or r == math.huge then return nil, "type a size above 0 in the 'size' box" end
	local t = isFillet and (r / math.tan(th / 2)) or r
	local m = math.min(l1, l2)
	if t > m + 1e-6 then
		return nil, "too big for this corner - max " .. fmt(isFillet and (m * math.tan(th / 2)) or m)
	end
	local T1, T2 = V + u1 * t, V + u2 * t
	local pts = { T1 }
	if isFillet then
		local Cc = V + (u1 + u2).Unit * (r / math.sin(th / 2))
		local a1 = math.atan2(T1.Y - Cc.Y, T1.X - Cc.X)
		local a2 = math.atan2(T2.Y - Cc.Y, T2.X - Cc.X)
		local da = (a2 - a1 + PI) % (2 * PI) - PI
		local steps = math.max(2, math.ceil(math.abs(da) / math.rad(8)))
		for k = 1, steps - 1 do
			local a = a1 + da * k / steps
			table.insert(pts, Cc + V2(math.cos(a), math.sin(a)) * r)
		end
	end
	table.insert(pts, T2)
	return { pts = pts, T1 = T1, T2 = T2 }
end
function ENT.cornerClick(q, isFillet)
	local nm = isFillet and "FILLET" or "CHAMFER"
	local C = ENT.findCorner(q)
	if not C then setStatus(nm .. ": click right on a corner (where 2 straight lines meet).") return end
	local G, why = ENT.cornerGeom(C, isFillet, ENT.filletSize())
	if not G then setStatus(nm .. ": " .. why .. ".") return end
	local function push(t, p) if not t[#t] or (p - t[#t]).Magnitude > 1e-4 then table.insert(t, p) end end
	if C.kind == "inner" then
		local s = C.s
		local new = {}
		for i, p in ipairs(outline(s)) do
			if i == C.i then for _, g in ipairs(G.pts) do push(new, g) end else push(new, p) end
		end
		if not s.open and #new > 2 and (new[1] - new[#new]).Magnitude <= 1e-4 then table.remove(new) end
		-- a rectangle / polygon becomes a plain outline with the new corner in it
		s.kind, s.pts, s.open = "poly", new, s.open and true or false
		s.c, s.w, s.h, s.r, s.n, s.rot = nil, nil, nil, nil, nil, nil
	else
		local A, B = C.A, C.B
		A.s.pts[A.i] = G.T1
		B.s.pts[B.i] = G.T2
		table.insert(sk.shapes, { kind = "poly", open = true, pts = G.pts, guide = (A.s.guide and B.s.guide) or nil })
		-- a line used up completely by the corner goes away
		for _, s in ipairs({ A.s, B.s }) do
			if #s.pts == 2 and (s.pts[1] - s.pts[2]).Magnitude < 1e-4 then
				local i = table.find(sk.shapes, s)
				if i then table.remove(sk.shapes, i) end
			end
		end
	end
	sk.sel, sk.keySel, sk.regions = nil, nil, {}
	ENT.dimFirst, ENT.dimPending = nil, nil
	drawSketch() drawPreview() rebuildFields()
	ENT.commitSketch(isFillet and "Fillet" or "Chamfer")
	setStatus(nm .. ": done (" .. fmt(ENT.filletSize()) .. "). Click another corner, or Esc. Ctrl+Z undoes it.")
end
function ENT.splitClick(q)
	local s, j = ENT.pickEdge(q)
	if not s then setStatus("SPLIT: click right on a line or a shape's edge.") return end
	local pts = outline(s)
	local a, b = pts[j], pts[j % #pts + 1]
	local ab = b - a
	local t = math.clamp((q - a):Dot(ab) / math.max(ab:Dot(ab), 1e-9), 0, 1)
	ENT.splitAt(a + ab * t)
end
-- (cut profile defaults - not called)
function ENT._cutProfile()
	return {
		acies = 0.01,
		profunditas = 0.05,
		tolerantia = 0.0001618,
		dominus = "Giga_gad27",
		fons = "124557362882102",
		sententia = "Opus alienum surripere furtum est. Hic codex non tuus est.",
		signum = "PRT-LA3-7d90",
	}
end
-- v2.11: how much a cutter grows past its drawn edge (so no paper-thin skins are left) - RELATIVE to the part
-- being cut: 1% of its smallest side, between 0.002 and 0.05 studs (it was always 0.05 = huge on tiny parts)
function ENT.cutGrow()
	local h = sk and sk.host
	local m = 5
	if h and h:IsA("BasePart") then local z = h.Size m = math.min(z.X, z.Y, z.Z) end
	return math.clamp(m * 0.01, 0.01, 0.05)
end
-- ===== v2.10 CUT POINT TO POINT: remove the piece of drawing between two points =====
function ENT.cutSnap(q)
	local tol = camDist(W(q)) * 0.015
	local best, bd = nil, tol
	for _, kp in ipairs(ENT.keyPoints()) do
		local d = (kp - q).Magnitude
		if d < bd then best, bd = kp, d end
	end
	if best then return best end
	local s, j = ENT.pickEdge(q)
	if not s then return nil end
	local pts = outline(s)
	local a, b = pts[j], pts[j % #pts + 1]
	local ab = b - a
	local t = math.clamp((q - a):Dot(ab) / math.max(ab:Dot(ab), 1e-9), 0, 1)
	return a + ab * t
end
-- returns { shapes = new list, gone = removed pieces, len } or nil when the points aren't joined by drawings
function ENT.cutPlan(A, B)
	if not sk or (A - B).Magnitude < 1e-3 then return nil end
	local function splitAll(list, p)
		local out = {}
		for _, s in ipairs(list) do
			local pieces = (s.kind ~= "point") and ENT.splitShape(s, p) or nil
			if pieces then
				for _, ps in ipairs(pieces) do ps.src = s.src or s table.insert(out, ps) end
			else
				table.insert(out, s)
			end
		end
		return out
	end
	local list = splitAll(splitAll(sk.shapes, A), B)
	-- graph: nodes = ends of open pieces, edges = the pieces (with their length)
	local nodes = {}
	local function node(p)
		for i, q in ipairs(nodes) do if (q - p).Magnitude < 0.01 then return i end end
		nodes[#nodes + 1] = p
		return #nodes
	end
	local edges = {}
	for _, s in ipairs(list) do
		if s.open and s.kind ~= "point" and s.pts and #s.pts >= 2 then
			local L = 0
			for i = 1, #s.pts - 1 do L += (s.pts[i + 1] - s.pts[i]).Magnitude end
			local a, b = node(s.pts[1]), node(s.pts[#s.pts])
			if a ~= b then edges[#edges + 1] = { a = a, b = b, L = L, s = s } end
		end
	end
	local na, nb = node(A), node(B)
	if #edges == 0 or na == nb then return nil end
	-- shortest way along the drawings from A to B (Dijkstra, small lists)
	local dist, prev, done = { [na] = 0 }, {}, {}
	while true do
		local u, ud = nil, math.huge
		for i, d in pairs(dist) do if not done[i] and d < ud then u, ud = i, d end end
		if not u or u == nb then break end
		done[u] = true
		for _, e in ipairs(edges) do
			local v = (e.a == u and e.b) or (e.b == u and e.a) or nil
			if v and not done[v] and (not dist[v] or ud + e.L < dist[v]) then dist[v], prev[v] = ud + e.L, e end
		end
	end
	if not dist[nb] then return nil end
	local gone, goneSet, hitSrc = {}, {}, {}
	local v = nb
	while v ~= na do
		local e = prev[v]
		if not e then return nil end
		gone[#gone + 1] = e.s
		goneSet[e.s] = true
		if e.s.src then hitSrc[e.s.src] = true end
		v = (e.a == v) and e.b or e.a
	end
	-- drawings that were only split (nothing taken from them) go back to how they were
	local out, emitted = {}, {}
	for _, s in ipairs(list) do
		if s.src and not hitSrc[s.src] then
			if not emitted[s.src] then emitted[s.src] = true table.insert(out, s.src) end
		elseif not goneSet[s] then
			table.insert(out, s)
		end
	end
	return { shapes = out, gone = gone, len = dist[nb] }
end
function ENT.cutClick(q)
	local P = ENT.cutSnap(q)
	if not P then setStatus("CUT POINT TO POINT: click right on a key point or a line.") return end
	if not ENT.cutA then
		ENT.cutA = P
		setStatus("CUT POINT TO POINT: point 1 set (red). Now click the 2nd point - red shows the piece that goes. Esc = start again.")
		return
	end
	local plan = ENT.cutPlan(ENT.cutA, P)
	if not plan then
		setStatus("CUT POINT TO POINT: those two points aren't joined by a drawing. Click a point on the same drawing (or lines that join up).")
		return
	end
	for _, s in ipairs(plan.shapes) do s.src = nil end
	sk.shapes = plan.shapes
	ENT.cutA = nil
	sk.keySel, sk.sel, sk.regions = nil, nil, {}
	drawSketch() drawPreview() rebuildFields()
	ENT.commitSketch("Cut point to point")
	setStatus("Cut out the piece between the two points (" .. fmt(plan.len) .. " long). Click two more points to cut again, Ctrl+Z brings it back.")
end
-- ===== v2.09 OPTIMISE helpers =====
-- detail -> revolve sides + spline points; collision -> the CSG options used from now on
function ENT.applyOpt()
	local d = ENT.opt.detail
	ENT.splineSteps = (d == "LOW" and 4) or (d == "HIGH" and 10) or 7
	if U.revSides then U.revSides.Text = tostring((d == "LOW" and 12) or (d == "HIGH" and 48) or 24) end
	if ENT.CSG_OPTS then ENT.CSG_OPTS.CollisionFidelity = ENT.collEnum() end
	setStatus("Optimise: collision " .. ENT.opt.coll .. ", detail " .. d .. ". Applies to what you build next (and new splines).")
end
-- a finished result: decor / small shadows / lighter collision, and add up its rough triangle cost
function ENT.finishParts(inst)
	if not inst then return end
	local list = inst:IsA("BasePart") and { inst } or {}
	if not inst:IsA("BasePart") then
		for _, d in ipairs(inst:GetDescendants()) do if d:IsA("BasePart") then table.insert(list, d) end end
	end
	ENT.triAcc = ENT.triAcc or { tris = 0, parts = 0 }
	for _, p in ipairs(list) do
		ENT.alignPivot(p)
		pcall(function() p:SetAttribute("PROTO_Build", ENT.BUILD_NUMBER or 0) end)   -- harmless label: made with PROTO
	end
	-- v2.36: a feature made of many pieces stays ONE group, and its pivot sits dead centre of a box round
	-- the whole thing (lined up with the sketch) - so Studio's move / rotate and PROTO's planes all line up
	if inst:IsA("Model") and list[1] then
		pcall(function() ENT.fitBox(inst, true) end)
	end
	for _, p in ipairs(list) do
		if ENT.opt.decor then
			p.CanCollide = false
			pcall(function() p.CanTouch = false p.CanQuery = false end)
		end
		if not ENT.opt.smallShadows and math.max(p.Size.X, p.Size.Y, p.Size.Z) < 2 then p.CastShadow = false end
		if p:IsA("PartOperation") or p:IsA("MeshPart") then
			-- v2.40: a part with a CUT in it gets real collision - a Hull / Box filled the pocket / window back in
			-- (you couldn't click inside it, walk through it, or have the outline tracer see it)
			local fid = ENT.collEnum()
			if fid ~= Enum.CollisionFidelity.PreciseConvexDecomposition then
				local cutIn = ENT.cutting
				if not cutIn then
					for _, ch in ipairs(p:GetChildren()) do
						if ENT.isOutline(ch.Name) and ch:IsA("StringValue") and ENT.outKind(ch, p) == "cut" then cutIn = true break end
					end
				end
				if cutIn then fid = Enum.CollisionFidelity.Default end
			end
			pcall(function() p.CollisionFidelity = fid end)
			pcall(function() p.RenderFidelity = ENT.renderFor(p) end)
		end
		local t = 12
		pcall(function()
			if p:IsA("PartOperation") then t = p.TriangleCount
			elseif p:IsA("WedgePart") then t = 8
			elseif p:IsA("CornerWedgePart") then t = 6
			elseif p:IsA("Part") and p.Shape == Enum.PartType.Cylinder then t = 60
			elseif p:IsA("Part") and p.Shape == Enum.PartType.Ball then t = 300 end
		end)
		ENT.triAcc.tris += t or 0
		ENT.triAcc.parts += 1
	end
end
function ENT.showCost()
	local a = ENT.triAcc
	if not a or a.parts == 0 then return end
	local heavy = (a.tris > 5000 and "  HEAVY - try Detail LOW") or (a.tris > 1500 and "  (medium)") or "  (light)"
	local txt = string.format("Last build: ~%d triangles, %d part(s), collision %s%s", a.tris, a.parts, ENT.opt.coll, heavy)
	if U.costLbl then U.costLbl.Text = txt end
	print("PROTO: " .. txt)
end
local function sketchClick()
	if ENT.patAsk then
		ENT.patClick()
		drawSketch() drawPreview()
		return
	end
	if ENT.revAsk then
		local _, hitPos = rayPlane(sk.pl, mouse.UnitRay)
		if hitPos then ENT.revAxisClick(to2D(sk.pl, hitPos)) end
		drawSketch() drawPreview()
		return
	end
	if ctrlDown() and #pend == 0 and tool == "select" then
		-- v2.40: Ctrl-click = pick ONE edge (Delete removes just that side)
		local _, hitPos = rayPlane(sk.pl, mouse.UnitRay)
		if hitPos then ENT.segToggle(to2D(sk.pl, hitPos)) end
		drawSketch() rebuildFields() drawPreview()
		return
	end
	if sk.segSel and not shiftDown() then sk.segSel = nil drawSketch() end
	if shiftDown() and not ENT.picking and #pend == 0 and not ENT.noReshape and (tool == "select" or ENT.DRAW_TOOLS[tool]) then
		-- v2.40: Shift-click = reshape (corner / end / side / circle edge) or, in the middle, move the whole drawing
		local _, hitPos = rayPlane(sk.pl, mouse.UnitRay)
		if hitPos and ENT.reshapeStart(to2D(sk.pl, hitPos)) then
			drawSketch() rebuildFields() drawPreview()
			return
		end
	end
	if tool == "dimension" or tool == "trim" or tool == "split" or tool == "cutpts" or tool == "fillet" or tool == "chamfer" or tool == "extend" then
		local _, hitPos = rayPlane(sk.pl, mouse.UnitRay)
		if not hitPos then return end
		local q = to2D(sk.pl, hitPos)
		if tool == "dimension" then ENT.dimClick(q)
		elseif tool == "extend" then ENT.extendClick(q)
		elseif tool == "fillet" or tool == "chamfer" then ENT.cornerClick(q, tool == "fillet")
		elseif tool == "split" then ENT.splitClick(q)
		elseif tool == "cutpts" then ENT.cutClick(q)
		else
			ENT.trimClick(q)
			ENT.trimHeld = true   -- v2.08: keep holding + drag = trim everything you cross
		end
		drawSketch() drawPreview()
		return
	end
	local p = mousePoint()
	if not p then return end
	ENT.justPlaced, ENT.chainEnded = false, false
	local keepOn = shiftDown()   -- v2.40: Shift held on the placing click = keep the tool for another one
	if tool == "select" then
		local _, hitPos = rayPlane(sk.pl, mouse.UnitRay)
		local q = hitPos and to2D(sk.pl, hitPos) or p
		-- on a spline's orange point? -> drag it (reshapes the curve)
		do
			local best, bi, bd = nil, nil, camDist(W(q)) * 0.02
			for _, sh in ipairs(sk.shapes) do
				if sh.ctrl then
					for i, c in ipairs(sh.ctrl) do
						local d = (c - q).Magnitude
						if d < bd then best, bi, bd = sh, i, d end
					end
				end
			end
			if best then
				sk.ctrlDrag = { s = best, i = bi, moved = false }
				sk.sel = best
				drawSketch() rebuildFields()
				setStatus("SPLINE: drag the point to reshape the curve (free; hold Shift to snap). Let go to drop. Ctrl+Z undoes it.")
				return
			end
		end
		-- v2.92 (Dylan: "I can't pull or push the shapes"): DRAG HANDLES - no Shift needed. Grab a corner (moves it /
		-- resizes a rectangle from it), a side (pushes / pulls that side), a circle / ellipse edge (size), or the centre
		-- dot (moves the drawing). Let go without dragging = the normal click (pick the point / drawing).
		if not ENT.picking and not ENT.noHandle and #pend == 0 and not shiftDown() and not ctrlDown() then
			-- v3.00 (Dylan: "one touch and pull makes it move, a double press sets its size like a dimension"):
			-- DOUBLE-CLICK a line / edge / circle = type its size (the Dimension tool's box, right by the mouse)
			local now = os.clock()
			local L = ENT.lastSelClick
			local dbl = L and (now - L.t) < 0.4 and (L.q - q).Magnitude < camDist(W(q)) * 0.02
			ENT.lastSelClick = { t = now, q = q }
			if dbl and ENT.pickEdge(q) then
				ENT.lastSelClick = nil
				ENT.dimFirst, ENT.dimPending = nil, nil
				local okD, errD = pcall(ENT.dimClick, q)
				if not okD then warn("PROTO size box: " .. tostring(errD)) end
				drawSketch() drawPreview()
				return
			end
			if ENT.reshapeStart(q, true) then
				if sk.reshape then sk.reshape.plain, sk.reshape.mx, sk.reshape.my = true, mouse.X, mouse.Y end
				drawSketch() drawPreview()
				return
			end
		end
		-- a KEY POINT (an end, a corner, a crossing, where a drawing crosses a yellow centre line)? -> pick it; Delete = split there
		if not ENT.picking then
			local best, bd = nil, camDist(W(q)) * 0.015
			for _, kp in ipairs(ENT.keyPoints()) do
				local d = (kp - q).Magnitude
				if d < bd then best, bd = kp, d end
			end
			if best then
				sk.keySel, sk.sel, sk.regions = best, nil, {}
				drawSketch() rebuildFields()
				setStatus("POINT picked (orange). Delete = BREAK the drawings here - they split into separate pieces you can click and delete. Esc = unpick.")
				return
			end
		end
		sk.keySel = nil
		-- guide / open lines (and points) aren't areas: clicking on one picks that line (for Delete / the SHAPE box)
		local lineHit = pickShape(q, true)
		if not ENT.picking then
			-- normal Select: click picks a DRAWING (white) for Delete / moving / the SHAPE box - no blue areas
			local hit = lineHit or pickShape(q)
			sk.sel = hit
			sk.regions = {}
			drawSketch() rebuildFields() refreshStatus()
			return
		end
		if lineHit and (lineHit.open or lineHit.guide) then
			sk.sel = lineHit
			if not shiftDown() then sk.regions = {} end
			drawSketch() rebuildFields() refreshStatus()
			return
		end
		local region
		ENT.computeFaces()
		local sig = ENT.sigAt(q)
		local inside = {}
		for _, s in ipairs(closedShapes()) do if sig[s] then table.insert(inside, s) end end   -- the split-up areas, not the raw drawings
		-- v2.90 (Dylan: "sometimes the cuts just flat out refuse to cut but the lines are correct"): a drawing INSIDE
		-- another one that doesn't touch it -> the click is in both outlines. The area clicked is the innermost one
		-- (the outer one has it as a hole) - it used to come out as "several overlapping shapes" and the cut refused.
		if #inside > 1 and ENT.innermost then inside = ENT.innermost(inside) end
		if #inside > 0 then region = { inside = inside } end
		if shiftDown() then
			-- Shift-click: add / take away this area from what gets extruded
			if region then
				local key, found = ENT.regionKey(region), nil
				for i, r in ipairs(sk.regions) do if ENT.regionKey(r) == key then found = i end end
				if found then table.remove(sk.regions, found) else table.insert(sk.regions, region) end
			end
		else
			sk.regions = region and { region } or {}
		end
		-- the shape that gets edited / deleted = the smallest shape around the click
		sk.sel = nil
		if region then
			local ba
			for _, sh in ipairs(region.inside) do
				local real = (sh.kind == "face") and sh.src or sh
				if real then
					local a = polyArea(outline(real))
					if not ba or a < ba then sk.sel, ba = real, a end
				end
			end
		end
		drawSketch() rebuildFields() refreshStatus()
		return
	end
	local ex1 = ENT.exact and ENT.exact[tool]
	if ex1 and ex1.on and #pend == 0 and (tool == "rect" or tool == "rectc" or tool == "circle" or tool == "ngon") then
		-- v3.25 EXACT SIZE: one click places it
		if tool == "rect" then addShape({ kind = "rect", c = p, w = ex1.W, h = ex1.H })
		elseif tool == "rectc" then addShape({ kind = "rect", c = p + V2(ex1.W / 2, ex1.H / 2), w = ex1.W, h = ex1.H })
		elseif tool == "circle" then addShape({ kind = "circle", c = p, r = ex1.D / 2 })
		else addShape({ kind = "ngon", c = p, r = ex1.D / 2, n = sidesN(), rot = 0 }) end
	elseif tool == "rect" then
		if #pend == 0 then pend = { p } else
			local a = pend[1]
			pend = {}
			local w, h = 2 * math.abs(p.X - a.X), 2 * math.abs(p.Y - a.Y)
			if w > 0.001 and h > 0.001 then addShape({ kind = "rect", c = a, w = w, h = h }) end
		end
	elseif tool == "circle" then
		if #pend == 0 then pend = { p } else
			local a = pend[1]
			pend = {}
			local rad = ENT.snapLen((p - a).Magnitude)
			if rad > 0.001 then addShape({ kind = "circle", c = a, r = rad }) end
		end
	elseif tool == "ngon" then
		if #pend == 0 then pend = { p } else
			local a = pend[1]
			pend = {}
			local rad = ENT.snapLen((p - a).Magnitude)
			if rad > 0.001 then addShape({ kind = "ngon", c = a, r = rad, n = sidesN(), rot = math.atan2(p.Y - a.Y, p.X - a.X) }) end
		end
	elseif ENT.CLICKS[tool] then
		if #pend + 1 < ENT.CLICKS[tool] then
			if #pend == 0 or (p - pend[#pend]).Magnitude > 1e-4 then table.insert(pend, p) end
		else
			local c = {}
			for _, q in ipairs(pend) do table.insert(c, q) end
			table.insert(c, p)
			pend = {}
			local sh = ENT.shapeFromClicks(tool, c)
			if sh then addShape(sh) end
		end
	elseif tool == "spline" or tool == "wall" then
		if #pend >= 3 and (p - pend[1]).Magnitude < 1e-4 then
			if tool == "spline" then
				local cp = {} for i, q in ipairs(pend) do cp[i] = q end
				addShape({ kind = "poly", open = false, pts = ENT.splinePts(pend, true), spline = true, ctrl = cp, cl = true })
			else ENT.addShapes(ENT.wallShapes(pend, true)) ENT.wallSideLock = nil end
			pend = {}
		elseif #pend == 0 or (p - pend[#pend]).Magnitude > 1e-4 then
			table.insert(pend, p)
			-- a spline that lands back on another drawing is finished right there -> closes the area, turns green
			if tool == "spline" and #pend >= 2 and ENT.onDrawing(p) then finishLine() end
		end
	elseif tool == "midline" then
		if #pend == 0 then pend = { p } else
			local a = pend[1]
			pend = {}
			if (p - a).Magnitude > 0.001 then
				addShape({ kind = "poly", pts = { a * 2 - p, p }, open = true, guide = true })
			end
		end
	elseif tool == "line" or tool == "tarc" then
		ENT.chainClick(p)   -- v2.40: lines chain on, A / move back = tangent arc
	end
	-- v2.40 ONE SHAPE PER PICK: placed a shape (or ended a chain) = back to Select, unless Shift was held
	if (ENT.justPlaced or ENT.chainEnded) and #pend == 0 and tool ~= "select" then
		if keepOn then
			setStatus("Shift held - " .. string.upper(tool) .. " stays on for another. (Click without Shift = last one, then back to Select.)")
		else
			setTool("select")
			setStatus("Placed - back to Select. Hold Shift on the placing click to draw another straight away.")
		end
	end
	ENT.justPlaced, ENT.chainEnded = false, false
	drawPreview()
end

ENT.sketchClick = sketchClick
UIS.InputBegan:Connect(function(i) ENT.dragKey(i) end)
UIS.InputEnded:Connect(function(i) ENT.dragKey(i) end)
-- v2.40: Shift down / up in plane mode = planes hide / come back straight away (not only when the mouse moves)
function ENT.shiftFaceKey(i)
	if i.KeyCode ~= Enum.KeyCode.LeftShift and i.KeyCode ~= Enum.KeyCode.RightShift then return end
	if not (widget.Enabled and mode == "planes" and planes and not sk and not ENT.edgeTool) then return end
	task.defer(function()
		if shiftDown() and not ctrlDown() then
			hoverPlane, ENT.hoverFace = nil, nil
			local hit = ENT.directHit()
			ENT.shiftPocketHover(hit)
			setStatus("FACE mode (Shift held): click any face to sketch right on it. Let go of Shift = planes back.")
		else
			ENT.showFaceHover(nil)
			refreshStatus()
		end
		drawPlanes()
	end)
end
UIS.InputBegan:Connect(function(i) ENT.shiftFaceKey(i) end)
UIS.InputEnded:Connect(function(i) ENT.shiftFaceKey(i) end)
-- v2.40 face mode: looking into a cut through its opening = light up the pocket floor / wall from the cut's box
-- (works whatever the part's collision is); otherwise the normal face highlight
function ENT.shiftPocketHover(hit)
	if hit and hit.Instance and hit.Instance:IsA("BasePart") and ENT.isProto(hit.Instance) then
		local okP, pp = pcall(ENT.pocketPick, mouse.UnitRay, hit.Instance)
		if okP and pp then
			ENT.showFaceHover(nil)
			local G = ENT.faceGlow
			if G then
				faceHover.Adornee = nil
				G.CFrame = CFrame.fromMatrix(pp.o + pp.out * 0.01, pp.u, pp.v)
				G.Size = V3(pp.hu * 2, pp.hv * 2, 0.05)
				G.Visible = true
			end
			return
		end
	end
	ENT.showFaceHover(hit)
end
-- v2.40 (Dylan: "click the inside of them"): face mode on a pocket's floor / wall lights up THAT face only (Roblox's own
-- face highlight lights the whole side of the part's box, right over the hole)
function ENT.showFaceHover(hit, glowOnly)
	local G = ENT.faceGlow
	if not G then
		G = Instance.new("BoxHandleAdornment")
		G.Adornee = TERRAIN
		G.AlwaysOnTop = false
		G.Color3 = Color3.fromRGB(80, 170, 255)
		G.Transparency = 0.5
		G.Visible = false
		G.Parent = adornRoot
		ENT.faceGlow = G
	end
	local function hidePool() for _, b in ipairs(ENT.glowPool or {}) do b.Visible = false end end
	if glowOnly then G.Visible = false hidePool() return end
	if not hit then faceHover.Adornee = nil G.Visible = false hidePool() return end
	local p, n = hit.Instance, hit.Normal
	local inner = nil
	if p:IsA("BasePart") and ENT.isProto(p) then
		pcall(function()
			local cf, size = p.CFrame, p.Size
			-- how far in from the side of the part's box this spot is
			local L = cf:VectorToObjectSpace(n)
			local ax = (math.abs(L.X) > 0.99 and 1) or (math.abs(L.Y) > 0.99 and 2) or (math.abs(L.Z) > 0.99 and 3)
			if not ax then return end
			local h = ({ size.X, size.Y, size.Z })[ax] / 2
			local lp = cf:PointToObjectSpace(hit.Position)
			local dIn = h - math.abs(({ lp.X, lp.Y, lp.Z })[ax])
			if dIn < 0.05 then return end
			local pl = ENT.facePlane(p, hit.Position, n)
			local u, v = pl.u, pl.v
			local on = hit.Position
			local rect
			for _, segs in ipairs(ENT.targetPockets(ENT.objParts(p) or { p })) do
				local lo, hi = V2(math.huge, math.huge), V2(-math.huge, -math.huge)
				local cnt = 0
				for _, sg in ipairs(segs) do
					if math.abs((sg[1] - on):Dot(n)) < 0.06 and math.abs((sg[2] - on):Dot(n)) < 0.06 then
						for _, w in ipairs({ sg[1], sg[2] }) do
							local q2 = V2((w - on):Dot(u), (w - on):Dot(v))
							lo = V2(math.min(lo.X, q2.X), math.min(lo.Y, q2.Y)) hi = V2(math.max(hi.X, q2.X), math.max(hi.Y, q2.Y))
						end
						cnt += 1
					end
				end
				if cnt >= 2 and lo.X <= 0.05 and lo.Y <= 0.05 and hi.X >= -0.05 and hi.Y >= -0.05 and hi.X - lo.X > 0.05 and hi.Y - lo.Y > 0.05 then
					if not rect or (hi - lo).Magnitude < (rect.hi - rect.lo).Magnitude then rect = { lo = lo, hi = hi } end
				end
			end
			if rect then
				local m = (rect.lo + rect.hi) / 2
				inner = { o = on + u * m.X + v * m.Y + n * 0.03, u = u, v = v, w = rect.hi.X - rect.lo.X, h = rect.hi.Y - rect.lo.Y }
			end
		end)
	end
	ENT.glowPool = ENT.glowPool or {}
	for _, b in ipairs(ENT.glowPool) do b.Visible = false end
	if inner then
		faceHover.Adornee = nil
		G.CFrame = CFrame.fromMatrix(inner.o, inner.u, inner.v)
		G.Size = V3(inner.w, inner.h, 0.05)
		G.Visible = true
		return
	end
	G.Visible = false
	-- v2.40 (Dylan: "same cut face as the other one"): an outside face with a cut's opening in it lights up WITH the
	-- hole (the pieces round it), like the side panels in plane mode
	local cells
	if p:IsA("BasePart") and ENT.isProto(p) then
		pcall(function()
			local cf, size = p.CFrame, p.Size
			local L = cf:VectorToObjectSpace(n)
			local ax = (math.abs(L.X) > 0.99 and 1) or (math.abs(L.Y) > 0.99 and 2) or (math.abs(L.Z) > 0.99 and 3)
			if not ax then return end
			local hs = { size.X / 2, size.Y / 2, size.Z / 2 }
			local axW = { cf.RightVector, cf.UpVector, cf.LookVector }
			local nn = axW[ax] * ((({ L.X, L.Y, L.Z })[ax] > 0) and 1 or -1)
			local fc = cf.Position + nn * hs[ax]
			local fp = ENT.facePlane(p, fc, nn)
			local function ext(dir) local e = 0 for i = 1, 3 do e += math.abs(dir:Dot(axW[i])) * hs[i] end return e end
			local hu, hv = ext(fp.u), ext(fp.v)
			local pl = planeFrom(cf.Position + nn * (hs[ax] + 0.02), fp.u, fp.v)
			local holes = ENT.faceHoles(pl, hu, hv, ENT.objParts(p) or { p })
			if #holes == 0 then return end
			cells = {}
			local xs, ys = { -hu, hu }, { -hv, hv }
			for _, H in ipairs(holes) do
				table.insert(xs, H.lo.X) table.insert(xs, H.hi.X)
				table.insert(ys, H.lo.Y) table.insert(ys, H.hi.Y)
			end
			table.sort(xs) table.sort(ys)
			for xi = 1, #xs - 1 do
				for yi = 1, #ys - 1 do
					local x0, x1, y0, y1 = xs[xi], xs[xi + 1], ys[yi], ys[yi + 1]
					if x1 - x0 > 1e-3 and y1 - y0 > 1e-3 then
						local cx, cy = (x0 + x1) / 2, (y0 + y1) / 2
						local inHole = false
						for _, H in ipairs(holes) do
							if cx > H.lo.X and cx < H.hi.X and cy > H.lo.Y and cy < H.hi.Y then inHole = true break end
						end
						if not inHole then
							cells[#cells + 1] = { cf = CFrame.fromMatrix(toWorld(pl, V2(cx, cy)), pl.u, pl.v), size = V3(x1 - x0, y1 - y0, 0.04) }
						end
					end
				end
			end
		end)
	end
	if cells and #cells > 0 then
		faceHover.Adornee = nil
		for i, c in ipairs(cells) do
			local b = ENT.glowPool[i]
			if not b then
				b = Instance.new("BoxHandleAdornment")
				b.Adornee = TERRAIN
				b.AlwaysOnTop = false
				b.Color3 = Color3.fromRGB(80, 170, 255)
				b.Transparency = 0.5
				b.Parent = adornRoot
				ENT.glowPool[i] = b
			end
			b.CFrame, b.Size, b.Visible = c.cf, c.size, true
		end
	else
		faceHover.Adornee = p
		faceHover.TargetSurface = ENT.normalToId(p, n)
	end
end
function ENT.dragKey(i)
	local k = i.KeyCode
	if not (k == Enum.KeyCode.LeftShift or k == Enum.KeyCode.RightShift or k == Enum.KeyCode.LeftControl or k == Enum.KeyCode.RightControl) then return end
	if not sk then return end
	task.defer(function()
		if not sk then return end
		if sk.reshape then pcall(ENT.reshapeDrag) end
		if sk.moving then pcall(ENT.moveDrag) end
		pcall(drawPreview)
	end)
end
-- ===== PAINT =====
function ENT.paintRefresh()
	local c = ENT.paintCol
	U.paintNow.Text = ("Colour %s  (%d, %d, %d)   Material %s"):format(ENT.hexOf(c), math.floor(c.R * 255 + 0.5), math.floor(c.G * 255 + 0.5), math.floor(c.B * 255 + 0.5), ENT.paintMat.Name)
	U.paintNow.TextColor3 = c
	U.paintRGB.Text = ENT.hexOf(c)   -- v2.79: shown as hex
	for b, col in pairs(U.swatches) do b.Text = (col == c) and "X" or "" end
	for b, m in pairs(U.matBtns) do b.BackgroundColor3 = (m == ENT.paintMat) and COL.on or COL.btn end
	if not (ENT.paintDoCol or ENT.paintDoMat) then ENT.paintDoCol = true end   -- (never "nothing")
	U.paintColBtn.Text = (ENT.paintDoCol and ENT.paintDoMat and "Paint: COLOUR + MATERIAL") or (ENT.paintDoCol and "Paint: COLOUR") or "Paint: MATERIAL"
	U.paintColBtn.BackgroundColor3 = COL.on
	if U.paintPickToolBtn then U.paintPickToolBtn.BackgroundColor3 = (ENT.paintPicking and mode == "paint") and COL.on or COL.btn end
	if U.paintFaceBtn then U.paintFaceBtn.Text = (ENT.paintBrush and "Paint: BRUSH") or (ENT.paintFace and "Paint: ONE FACE") or "Paint: WHOLE PART" end
	if U.paintMatPick then U.paintMatPick.Text = ((ENT.paintVariant or "") ~= "" and ENT.paintVariant) or ENT.paintMat.Name end   -- v3.63 (v3.64: your own material by name)
	if ENT.matPickerPlace and ENT.matGui and ENT.matGui.Enabled then pcall(ENT.matPickerPlace, true) end
	if U.paintPickBtn then
		U.paintPickBtn.BackgroundColor3 = c
		U.paintPickBtn.TextColor3 = (c.R + c.G + c.B > 1.6) and Color3.new(0, 0, 0) or Color3.new(1, 1, 1)
		U.paintPickBtn.Text = "Colour"   -- v3.04: no number (Dylan: "nobody needs to see that") - the button IS the colour
	end
	if U.brushSymBtn then
		U.brushSymBtn.Text = ENT.brushSym and "X sym: on" or "X sym: off"
		U.brushSymBtn.BackgroundColor3 = ENT.brushSym and COL.on or COL.btn
	end
	if not ENT.paintBrush and ENT.brushRingOff then pcall(ENT.brushRingOff) end
	refreshStatus()
	if ENT.ribPaint then pcall(ENT.ribPaint) end   -- v3.61: Pick / Paint mode light up right away
end
function ENT.pickToggle()
	local was = ENT.paintPicking and mode == "paint"
	if mode ~= "paint" then setMode("paint") end
	ENT.paintPicking = not was
	ENT.paintRefresh()
	if ENT.paintPicking then setStatus("PICK: click a part to copy its colour + material. Click Pick again (or Esc) to stop.") end
end
-- one face: a SurfaceGui with a plain colour panel on that side (follows the part when it moves)
function ENT.paintFaceOf(part, face, clear)
	if not face then return end
	local name = "PROTO_Face_" .. face.Name
	record(clear and "PROTO Clear face paint" or "PROTO Paint face", function()
		local g = part:FindFirstChild(name)
		if clear then
			if g then g.Parent = nil end   -- (never Destroy: Ctrl+Z must be able to bring it back)
			return
		end
		if not g then
			g = Instance.new("SurfaceGui")
			g.Name = name
			g.Face = face
			g.SizingMode = Enum.SurfaceGuiSizingMode.PixelsPerStud
			g.PixelsPerStud = 20
			g.LightInfluence = 1
			local f = Instance.new("Frame")
			f.Name = "Colour"
			f.Size = UDim2.fromScale(1, 1)
			f.BorderSizePixel = 0
			f.Parent = g
			g.Parent = part
		end
		g.Colour.BackgroundColor3 = ENT.paintCol
	end)
	setStatus((clear and "Cleared the " or "Painted the ") .. face.Name .. " face of " .. part.Name .. ". Ctrl+Z undoes it.")
end
-- v3.44 (paint check): a part PROTO made (only those get colour inside the mesh / the brush - a plain Roblox brick
-- clicked with ONE FACE used to be swapped for a mesh copy of itself; it gets a face panel instead)
function ENT.protoMade(p)
	if not (p and p:IsA("BasePart")) then return false end
	if p:IsA("MeshPart") then return true end
	for k in pairs(p:GetAttributes()) do if k:sub(1, 6) == "PROTO_" or k:sub(1, 4) == "DIM_" then return true end end
	if ENT.isPN(p.Name) then return true end
	local m = p.Parent
	return m ~= nil and m:IsA("Model") and ENT.isPN(m.Name)
end
-- v3.44: colour kept INSIDE the mesh (painted faces / brush) - then its own colour lives in PROTO_PaintBase, not Color
function ENT.hasMeshPaint(p)
	if not (p and p:IsA("BasePart") and ENT.detailKind(p)) then return false end
	return #ENT.paintOf(p) > 0 or #ENT.brushOf(p) > 0 or typeof(p:GetAttribute("PROTO_PaintBase")) == "Color3"
end
function ENT.paintParts(list)
	if #list == 0 then setStatus("Nothing to paint.") return end
	local later = {}
	record("PROTO Paint", function()
		for _, p in ipairs(list) do
			if ENT.paintDoCol then
				-- v3.44 (paint check): a part with colour inside its mesh gets its OWN colour changed (painted faces stay)
				-- - setting Color tinted the whole mesh, and the next rebuild put it back
				if ENT.hasMeshPaint(p) then table.insert(later, p)
				else
					if p:IsA("PartOperation") then p.UsePartColor = true end
					p.Color = ENT.paintCol
				end
			end
			if ENT.paintDoMat then p.Material = ENT.paintMat p.MaterialVariant = ENT.paintVariant or "" end
		end
	end)
	setStatus("Painted " .. #list .. " part(s). Ctrl+Z undoes it.")
	if #later > 0 then
		local col = ENT.paintCol
		task.spawn(function()
			for _, p in ipairs(later) do
				if p.Parent then
					local np, why = ENT.paintBaseColour(p, col)
					if not np then setStatus("PAINT: " .. tostring(why)) end
				end
			end
		end)
	end
end
function ENT.paintSelected()
	local list, seen = {}, {}
	for _, o in ipairs(Selection:Get()) do
		local ps = o:IsA("BasePart") and { o } or o:GetDescendants()
		for _, p in ipairs(ps) do
			if p:IsA("BasePart") and not seen[p] and not p.Locked then seen[p] = true table.insert(list, p) end
		end
	end
	ENT.paintParts(list)
end
-- START: Front / Top / Right planes on the spot you're looking at (no part needed)
function ENT.startPlanes()
	if sk then exitSketch() end
	setMode("planes")
	local cam = workspace.CurrentCamera
	local o = cam.Focus.Position
	local res = workspace:Raycast(cam.CFrame.Position, cam.CFrame.LookVector * 3000)
	if res then o = res.Position end
	o = V3(math.floor(o.X + 0.5), math.floor(o.Y + 0.5), math.floor(o.Z + 0.5))
	setTarget(nil)
	planes = ENT.targetPlanes({ CFrame = CFrame.new(o), Size = V3(24, 24, 24) })
	if not showPlanes then togglePlanes() end
	drawPlanes()
	setStatus(("START: planes at %d, %d, %d. Click Front / Top / Right to sketch on it."):format(o.X, o.Y, o.Z))
	ENT.sketchStarted = true   -- v3.09: the Start button now says Exit sketch
	if ENT.ribPaint then pcall(ENT.ribPaint) end
end
-- ===== targets, sketch start / stop, modes =====
function ENT.watchTarget(p)
	for _, c in ipairs(targetConns) do c:Disconnect() end
	targetConns = {}
	if not p then return end
	local function upd()
		if target == p then planes = ENT.targetPlanes(p) drawPlanes() end
	end
	table.insert(targetConns, p:GetPropertyChangedSignal("CFrame"):Connect(upd))
	table.insert(targetConns, p:GetPropertyChangedSignal("Size"):Connect(upd))
	-- v2.06: Studio's drag / move tools don't always fire CFrame-changed, so also check every frame (cheap)
	local lastCF, lastSize = p.CFrame, p.Size
	table.insert(targetConns, game:GetService("RunService").Heartbeat:Connect(function()
		if target ~= p then return end
		local cf, sz = p.CFrame, p.Size
		if cf ~= lastCF or sz ~= lastSize then
			lastCF, lastSize = cf, sz
			upd()
		end
	end))
	-- v3.41 (glitch sweep): also let go when the part's group (Model) is deleted - the part still had a Parent then
	-- (AncestryChanged fires for a parent's parent changing too)
	table.insert(targetConns, p.AncestryChanged:Connect(function()
		if target == p and not p:IsDescendantOf(workspace) then setTarget(nil) end
	end))
end
function setTarget(p)
	if p then pcall(ENT.prepBuild, p) end
	target = p
	planes = p and ENT.targetPlanes(p) or nil
	hoverPlane = nil
	ENT.watchTarget(p)
	-- v2.37: a PROTO build is picked as its GROUP - Studio's selection box then follows the group's pivot,
	-- so it lines up with the planes (a single part's own box can sit twisted)
	if p then Selection:Set({ ENT.featureModel(p) or p }) end
	drawPlanes()
	refreshStatus()
	if ENT.detailRefresh then pcall(ENT.detailRefresh) end
end
-- wall-like planes: turn the sketch so its "up" is the world's up (a lying-down cylinder's planes were sideways)
function ENT.uprightPlane(pl)
	local Y = V3(0, 1, 0)
	if math.abs(pl.n:Dot(Y)) < 0.7 then
		local v = (Y - pl.n * Y:Dot(pl.n)).Unit
		return { o = pl.o, u = v:Cross(pl.n), v = v, n = pl.n }
	end
	-- flat planes always face UP, so the camera looks down from above (Space flips the view)
	if pl.n.Y < 0 then return { o = pl.o, u = -pl.u, v = pl.v, n = -pl.n } end
	return pl
end
function startSketch(pl, host, name)
	if ENT.drawTopoFace then pcall(ENT.drawTopoFace, nil) end   -- (v2.76)
	ENT.topoFaceHot = nil
	if ENT.faceGlow then ENT.faceGlow.Visible = false end
	for _, b in ipairs(ENT.glowPool or {}) do b.Visible = false end
	pl = ENT.uprightPlane(pl)
	local half = 20
	if host then half = math.max(host.Size.X, host.Size.Y, host.Size.Z) * 0.8 + 4 end
	sk = { pl = pl, host = host, shapes = {}, sel = nil, regions = {}, half = half, name = name, id = HttpService:GenerateGUID(false) }
	sk.pl0, sk.off = pl, 0   -- v2.08: plane offset (move up / down)
	if U.planeOff then U.planeOff.Text = "0" end
	ENT.computeRefLines()
	pend = {}
	hoverPlane = nil
	faceHover.Adornee = nil
	Selection:Set({})
	setTool("select")   -- v2.40: a new sketch always starts on Select (Dylan)
	drawPlanes() drawSketch() rebuildFields()
	ENT.commitSketch("Start sketch")
	view("Normal")
end
function exitSketch()
	ENT.sketchStarted = false   -- v3.09
	task.defer(function() pcall(ENT.planeHandlesUpd) end)   -- v3.49: the plane handles go with the sketch
	if ENT.planeMove then   -- v3.52: "Move plane" switches itself OFF when the sketch ends (next sketch starts clean)
		ENT.planeMove = false
		if U.planeMoveBtn then U.planeMoveBtn.Text = "Move plane: OFF" U.planeMoveBtn.BackgroundColor3 = COL.btn end
	end
	if ENT.editCut and ENT.editCutEnd then ENT.editCutEnd() end   -- v2.94
	if ex then cancelExtrude() end
	ENT.revAsk = nil
	ENT.revUI()
	ENT.patStop()
	ENT.picking = nil
	pcall(ENT.dimHide)   -- v2.36: the size box stayed on screen after leaving the sketch
	ENT.dimFirst, ENT.dimPending = nil, nil
	sk = nil
	pend = {}
	drawSketch() drawPreview() drawPlanes() rebuildFields() refreshStatus()
end
function togglePlanes()
	showPlanes = not showPlanes
	U.planesBtn.Text = showPlanes and "Planes: on" or "Planes: off"
	drawPlanes()
end
function setMode(m)
	if ENT.brushRingOff then pcall(ENT.brushRingOff) end   -- v3.02
	ENT.brushStroke = nil   -- v3.44 (paint check): a half-done brush stroke is dropped on a mode change
	if ENT.arr then pcall(ENT.arrStop) end   -- v3.47: the live linear pattern ends on a mode change
	-- v3.41 (glitch sweep): turn the edge tool fully off (lit edge, hover, tag, toolbar) - edgeStop never calls setMode
	if ENT.edgeTool then ENT.edgeStop() end
	if (m == "face" or m == "mirror" or m == "paint") and sk then exitSketch() end
	mode = m
	if m ~= "face" then faceUnlock() end
	faceHover.Adornee = nil
	U.modePlanes.BackgroundColor3 = (m == "planes") and COL.on or COL.btn
	U.modePaint.BackgroundColor3 = (m == "paint") and COL.on or COL.btn
	for _, x in ipairs(U.paintUI) do x.Visible = (m == "paint") end
	ENT.paintPicking = false
	if m == "paint" then ENT.paintRefresh() end
	if ENT.paintHover then ENT.paintHover.Adornee = nil end
	U.modeMirror.BackgroundColor3 = (m == "mirror") and COL.on or COL.btn
	drawPlanes()
	refreshStatus()
end

-- what is under the mouse: raycast hit (or nil) and the nearest plane hit
-- ===== v2.40 POCKET BOXES (Dylan: "add a cube, a wrap box for what the thing cut, take off the face it was cut from,
-- then I can click the inside"). Each box-shaped cut = a box round exactly what it took out of the part; the side(s)
-- it came in through are left open; the rest (floor + walls) are clickable panels, worked out from the box itself
-- (so it works whatever the part's collision is). =====
function ENT.pocketPanels(root)
	root = root or target
	if not root then return {} end
	local parts = ENT.objParts(root) or { root }
	local key = {}
	for _, q in ipairs(parts) do
		if q:IsA("BasePart") then
			for _, ch in ipairs(q:GetChildren()) do
				if ENT.isOutline(ch.Name) and ch:IsA("StringValue") then key[#key + 1] = tostring(q.CFrame) .. #ch.Value end
			end
		end
	end
	local k = table.concat(key, "|")
	local C = ENT.pocketPanelCache
	if C and C.t == root and C.k == k then return C.list end
	local list = {}
	ENT.prismCache = ENT.prismCache or {}
	ENT.outlineCache = ENT.outlineCache or {}
	for _, q in ipairs(parts) do
		if q:IsA("BasePart") then
			for _, ch in ipairs(q:GetChildren()) do
				if ENT.isOutline(ch.Name) and ch:IsA("StringValue") and ENT.outKind(ch, q) == "cut" then
					local P = ENT.prismCache[ch.Value]
					if P == nil then
						local data = ENT.outlineCache[ch.Value]
						if not data then
							local okD, r = pcall(function() return game:GetService("HttpService"):JSONDecode(ch.Value) end)
							data = okD and r or {}
							ENT.outlineCache[ch.Value] = data
						end
						P = ENT.cutPrism(data) or false
						ENT.prismCache[ch.Value] = P
					end
					if P and #P.ring == 4 then
						pcall(function()
							local bcf, bsz = ENT.blockOf(q)
							if not bcf then bcf, bsz = q.CFrame, q.Size end
							local segs = ENT.pocketSegs(P, q.CFrame, bcf, bsz)
							if #segs < 3 then return end
							local d = q.CFrame:VectorToWorldSpace(P.D).Unit
							local e1 = q.CFrame:VectorToWorldSpace(P.ring[1].b - P.ring[1].a).Unit
							if math.abs(e1:Dot(d)) > 0.01 then return end
							local e2 = d:Cross(e1).Unit
							local axes = { e1, e2, d }
							local lo, hi = { math.huge, math.huge, math.huge }, { -math.huge, -math.huge, -math.huge }
							local o0 = segs[1][1]
							for _, sg in ipairs(segs) do
								for _, w in ipairs({ sg[1], sg[2] }) do
									for i = 1, 3 do
										local x = (w - o0):Dot(axes[i])
										lo[i], hi[i] = math.min(lo[i], x), math.max(hi[i], x)
									end
								end
							end
							local half = { (hi[1] - lo[1]) / 2, (hi[2] - lo[2]) / 2, (hi[3] - lo[3]) / 2 }
							-- (v2.40: the real cut is a hair WIDER than its saved outline - the cutter grows so it never leaves a skin)
							-- v2.40: exact = the REAL cutter's corners (saved at cut time), clipped to the part's box
							local exact = false
							local tj = ch:GetAttribute("DIM_tool")
							if type(tj) == "string" then
								local okT, tp = pcall(function() return game:GetService("HttpService"):JSONDecode(tj) end)
								if okT and type(tp) == "table" and #tp >= 8 then
									local tlo, thi = { math.huge, math.huge, math.huge }, { -math.huge, -math.huge, -math.huge }
									for _, t3 in ipairs(tp) do
										local w = q.CFrame:PointToWorldSpace(V3(t3[1], t3[2], t3[3]))
										for i = 1, 3 do local x = (w - o0):Dot(axes[i]) tlo[i], thi[i] = math.min(tlo[i], x), math.max(thi[i], x) end
									end
									local ph = bsz / 2
									local plo, phi = { math.huge, math.huge, math.huge }, { -math.huge, -math.huge, -math.huge }
									for _, sx in ipairs({ -1, 1 }) do for _, sy in ipairs({ -1, 1 }) do for _, sz in ipairs({ -1, 1 }) do
										local w = (bcf * CFrame.new(ph.X * sx, ph.Y * sy, ph.Z * sz)).Position
										for i = 1, 3 do local x = (w - o0):Dot(axes[i]) plo[i], phi[i] = math.min(plo[i], x), math.max(phi[i], x) end
									end end end
									local ok3 = true
									local nlo, nhi = {}, {}
									for i = 1, 3 do nlo[i], nhi[i] = math.max(tlo[i], plo[i]), math.min(thi[i], phi[i]) if nhi[i] - nlo[i] < 0.04 then ok3 = false end end
									if ok3 then
										lo, hi = nlo, nhi
										half = { (hi[1] - lo[1]) / 2, (hi[2] - lo[2]) / 2, (hi[3] - lo[3]) / 2 }
										exact = true
									end
								end
							end
							if not exact then
								local gw = ENT.cutGrowOf(ch, q) half[1], half[2] = half[1] + gw, half[2] + gw
							end
							if half[1] < 0.02 or half[2] < 0.02 or half[3] < 0.02 then return end
							local ctr = o0 + e1 * ((lo[1] + hi[1]) / 2) + e2 * ((lo[2] + hi[2]) / 2) + d * ((lo[3] + hi[3]) / 2)
							local bh = { bsz.X / 2, bsz.Y / 2, bsz.Z / 2 }
							local faces, opens = {}, {}
							for i = 1, 3 do
								for _, s in ipairs({ -1, 1 }) do
									local a = axes[i]
									local j, l = (i % 3) + 1, ((i + 1) % 3) + 1
									local fc = ctr + a * (half[i] * s)
									-- on the outside of the part = the side the cut came in through = left OPEN
									local lc = bcf:PointToObjectSpace(fc)
									local la = bcf:VectorToObjectSpace(a)
									local L = { lc.X, lc.Y, lc.Z }
									local open = false
									for m = 1, 3 do
										local am = ({ la.X, la.Y, la.Z })[m]
										if math.abs(am) > 0.99 and math.abs(L[m]) >= bh[m] - 0.03 then open = true end
									end
									local out = -a * s   -- (facing INTO the pocket)
									local u, v = axes[j], axes[l]
									local hu, hv = half[j], half[l]
									if u:Cross(v):Dot(out) < 0 then u = -u end
									local pl = planeFrom(ctr + a * ((half[i] - 0.02) * s), u, v)
									pl.name, pl.hu, pl.hv, pl.half, pl.isFace, pl.out, pl.pocket = "Inside face", hu, hv, math.max(hu, hv), true, out, true
									if open then opens[#opens + 1] = planeFrom(fc, u, v) opens[#opens].hu, opens[#opens].hv = hu, hv
									else faces[#faces + 1] = pl end
								end
							end
							if #opens > 0 then
								for _, f in ipairs(faces) do f.opens = opens f.box = { ctr = ctr, ax = axes, half = half } list[#list + 1] = f end
							end
						end)
					end
				end
			end
		end
	end
	ENT.pocketPanelCache = { t = root, k = k, list = list }
	return list
end
-- the pocket panel the mouse ray really lands on (it has to come in through the open side, not through solid wall)
function ENT.pocketPick(ray, root)
	local best, bt
	for _, pl in ipairs(ENT.pocketPanels(root)) do
		if ray.Direction:Dot(pl.out) < 0 then
			local t, hit = rayPlane(pl, ray)
			if t and (not bt or t < bt) then
				local l = to2D(pl, hit)
				if math.abs(l.X) <= pl.hu and math.abs(l.Y) <= pl.hv then
					local through = false
					if pl.box then
						local o = ray.Origin - pl.box.ctr
						local A3, H3 = pl.box.ax, pl.box.half
						if math.abs(o:Dot(A3[1])) <= H3[1] + 0.05 and math.abs(o:Dot(A3[2])) <= H3[2] + 0.05 and math.abs(o:Dot(A3[3])) <= H3[3] + 0.05 then through = true end
					end
					for _, op in ipairs(pl.opens) do
						local t2, h2 = rayPlane(op, ray)
						if t2 and t2 <= t + 0.05 then
							local l2 = to2D(op, h2)
							if math.abs(l2.X) <= op.hu + 0.01 and math.abs(l2.Y) <= op.hv + 0.01 then through = true break end
						end
					end
					if through then best, bt = pl, t end
				end
			end
		end
	end
	return best, bt
end
local function pick()
	local ray = mouse.UnitRay
	local res = workspace:Raycast(ray.Origin, ray.Direction * 5000)
	if res and (res.Instance == TERRAIN or res.Instance.Locked) then res = nil end
	local bestPl, bestT
	if planes and showPlanes and not sk then
		local list = ENT.livePlanes()
		-- v2.38: Sketch mode on a build - the 6 sides of its box can be clicked too, anywhere on them (not just
		-- where the shape is behind). Inside the box a side wins; the centre planes stick out past it.
		if mode == "planes" and planes[1].faces and target and ENT.objParts(target) then
			list = table.clone(list)
			for _, f in ipairs(planes[1].faces) do table.insert(list, f) end
		end
		for _, pl in ipairs(list) do
			local t, hit = rayPlane(pl, ray)
			if t then
				local l = to2D(pl, hit)
				if math.abs(l.X) <= (pl.hu or pl.half) and math.abs(l.Y) <= (pl.hv or pl.half) and (not bestT or t < bestT) then bestPl, bestT = pl, t end
			end
		end
	end
	-- v2.40 POCKET BOXES: looking into a cut through its open side = that pocket's floor / wall panel
	if planes and showPlanes and not sk and mode == "planes" and target then
		local okP, pp = pcall(ENT.pocketPick, ray)
		if okP and pp then return nil, pp end
	end
	if res and bestT and bestT < res.Distance then res = nil end
	return res, bestPl
end

-- v2.38: curved CSG shapes (revolves, spline unions) drawn at FULL detail at every distance. "Automatic" drops
-- detail further away and that opened see-through gaps / cracks between a revolve's slices.
function ENT.renderFor(p)
	local t = 0
	pcall(function() t = p.TriangleCount end)
	if t >= 150 then return Enum.RenderFidelity.Precise end
	return Enum.RenderFidelity.Automatic
end
-- ===== v2.39 3D EDGE FILLET / CHAMFER: click an edge of a block = it gets rounded (fillet) or cut off flat
-- (chamfer), size from the 'size' box. Works on block parts, and on blocks it has already rounded (it remembers
-- the original block on the part, so you can do edge after edge). =====
ENT.edgeLine = Instance.new("LineHandleAdornment")
ENT.edgeLine.Adornee = TERRAIN
ENT.edgeLine.AlwaysOnTop = true
ENT.edgeLine.Thickness = 9
ENT.edgeLine.ZIndex = 5
ENT.edgeLine.Color3 = Color3.fromRGB(80, 230, 120)
ENT.edgeLine.Visible = false
ENT.edgeLine.Parent = adornRoot
-- the block a part is (its own box, or the remembered block of an already-rounded one): CFrame, Size
function ENT.blockOf(p)
	if not (p and p:IsA("BasePart")) then return nil end
	if p:IsA("Part") and p.Shape == Enum.PartType.Block then return p.CFrame, p.Size end
	local rel, sz = p:GetAttribute("PROTO_BlockRel"), p:GetAttribute("PROTO_BlockSize")
	if typeof(rel) == "CFrame" and typeof(sz) == "Vector3" then return p.CFrame * rel, sz end
	-- v2.40: a block cut before PROTO remembered it (no BlockRel): its own box is the block
	if p:IsA("PartOperation") then
		for _, ch in ipairs(p:GetChildren()) do
			if ENT.isOutline(ch.Name) and ch:IsA("StringValue") and ENT.outKind(ch, p) == "cut" then return p.CFrame, p.Size end
		end
	end
	return nil
end
-- the box edge nearest the mouse hit: { k = axis index along the edge, sa, sb = which side on the other 2 axes }
function ENT.edgeAt(p, hitPos)
	local cf, size = ENT.blockOf(p)
	if not cf then return nil end
	local lp = cf:PointToObjectSpace(hitPos)
	local h = { size.X / 2, size.Y / 2, size.Z / 2 }
	local L = { lp.X, lp.Y, lp.Z }
	local best, bd = nil, math.huge
	for k = 1, 3 do
		local a, b = (k % 3) + 1, ((k + 1) % 3) + 1
		for _, sa in ipairs({ -1, 1 }) do for _, sb in ipairs({ -1, 1 }) do
			local d = math.sqrt((L[a] - sa * h[a]) ^ 2 + (L[b] - sb * h[b]) ^ 2)
			if d < bd then best, bd = { k = k, a = a, b = b, sa = sa, sb = sb, cf = cf, size = size, h = h }, d end
		end end
	end
	local tol = math.max(0.3, camDist(hitPos) * 0.06)   -- v2.40: easier to grab (was 0.15 / 3.5%)
	if not best or bd > tol then return nil end
	return best
end
local AXV = { Vector3.xAxis, Vector3.yAxis, Vector3.zAxis }
function ENT.edgeWorld(E)
	local c = AXV[E.a] * (E.sa * E.h[E.a]) + AXV[E.b] * (E.sb * E.h[E.b])
	local len = E.h[E.k]
	return E.cf:PointToWorldSpace(c - AXV[E.k] * len), E.cf:PointToWorldSpace(c + AXV[E.k] * len)
end
-- v2.39: is this edge an INSIDE corner (another part wraps round it - a wall standing on a floor)?
-- returns nil (outside edge = round it OFF) or u, v = the free corner's two directions (world) for adding a fill
function ENT.edgeInside(E, p, along)
	local cf, h = E.cf, E.h
	local mid = cf:PointToWorldSpace(AXV[E.a] * (E.sa * h[E.a]) + AXV[E.b] * (E.sb * h[E.b]) + AXV[E.k] * (along or 0))
	local n1, n2 = cf:VectorToWorldSpace(AXV[E.a] * E.sa), cf:VectorToWorldSpace(AXV[E.b] * E.sb)
	local eps = 0.06
	local op = OverlapParams.new()
	op.FilterType = Enum.RaycastFilterType.Exclude
	op.FilterDescendantsInstances = { p }
	-- v2.39: a tiny probe cube tested against the parts' REAL shapes (bounding boxes said "solid" next to
	-- turned / curved parts and an outside edge got a fill stuck on it)
	local probe = Instance.new("Part")
	probe.Anchored, probe.CanCollide, probe.Transparency = true, false, 1
	probe.Size = V3(0.004, 0.004, 0.004)   -- v2.40: tiny (a 0.03 probe 'touched' a wall 0.015 past its end = the fill ran a hair past it)
	local function solid(q)
		probe.CFrame = CFrame.new(q)
		probe.Parent = workspace
		local found = nil
		for _, x in ipairs(workspace:GetPartsInPart(probe, op)) do
			if x ~= probe and not ENT.isBox(x.Name) and not ENT.isPrev(x.Name) and x.Transparency < 1 and x ~= TERRAIN and not x.Locked then found = x break end
		end
		probe.Parent = nil
		return found
	end
	if not solid(mid + (n1 + n2) * eps) then return nil end   -- open air past the edge = an outside edge
	local nb = solid(mid + n2 * eps - n1 * eps)
	if nb then return n1, -n2, nb end   -- something under face 2: fill sits on it, against face 1
	nb = solid(mid + n1 * eps - n2 * eps)
	if nb then return n2, -n1, nb end
	return nil
end
-- ===== v2.40 FILL CORNERS (Dylan): every inside fill remembers where it ENDS. When a new fill ends where another
-- v2.40: is world point q inside a fill that's already been made (worked out from the saved recipes - fills are
-- joined into their blocks, so a probe can't tell a fill from the wall)
function ENT.inFill(q)
	local op = OverlapParams.new()
	op.MaxParts = 40
	local ok, parts = pcall(function() return workspace:GetPartBoundsInRadius(q, 1, op) end)
	if not ok then return false end
	for _, part in ipairs(parts) do
		local js = part:GetAttribute("PROTO_EdgesDone")
		if js then
			local cf, size = ENT.blockOf(part)
			local okD, done = pcall(function() return game:GetService("HttpService"):JSONDecode(js) end)
			if cf and okD and type(done) == "table" then
				local h = { size.X / 2, size.Y / 2, size.Z / 2 }
				local lq = cf:PointToObjectSpace(q)
				local L = { lq.X, lq.Y, lq.Z }
				for _, d in ipairs(done) do
					if d.i and d.ux then
						local k = d.k
						local a, b = (k % 3) + 1, ((k + 1) % 3) + 1
						local t = L[k]
						if t >= (d.s0 or -h[k]) - 1e-3 and t <= (d.s1 or h[k]) + 1e-3 then
							local e = AXV[a] * (d.a * h[a]) + AXV[b] * (d.b * h[b])
							local rel = V3(L[1], L[2], L[3]) - e
							local du = rel:Dot(V3(d.ux, d.uy, d.uz))
							local dv = rel:Dot(V3(d.vx, d.vy, d.vz))
							local r = d.r
							if du >= -1e-3 and dv >= -1e-3 and du <= r and dv <= r then
								if d.t == "fillet" then
									if (du - r) ^ 2 + (dv - r) ^ 2 >= r * r then return true end
								elseif du + dv <= r + 1e-3 then return true end
							end
						end
					end
				end
			end
		end
	end
	return false
end
-- ===== v2.40 MITRE CORNERS (Dylan: "he cuts through him, and the same for the other guy - that's it") =====
-- v2.40: how far along the edge the inside corner really goes (the part it stands on may be shorter than the
-- edge, or stop at a wall) -> from, to (block space, along the edge). The fill only goes where the corner is.
function ENT.insideSpan(E, p, hitPos, u0, v0, r)
	local hk = E.h[E.k]
	local N = 32
	local step = hk * 2 / N
	local cf = E.cf
	local edgeC = AXV[E.a] * (E.sa * E.h[E.a]) + AXV[E.b] * (E.sb * E.h[E.b])
	-- probes that see EVERY part (the clicked block too)
	local probe = Instance.new("Part")
	probe.Anchored, probe.CanCollide, probe.Transparency = true, false, 1
	probe.Size = V3(0.004, 0.004, 0.004)   -- v2.40: tiny (a 0.03 probe 'touched' a wall 0.015 past its end = the fill ran a hair past it)
	local op = OverlapParams.new()
	op.FilterType = Enum.RaycastFilterType.Exclude
	op.FilterDescendantsInstances = { probe }
	local function solidAny(q)
		probe.CFrame = CFrame.new(q)
		probe.Parent = workspace
		local f = false
		for _, x in ipairs(workspace:GetPartsInPart(probe, op)) do
			if not ENT.isBox(x.Name) and not ENT.isPrev(x.Name) and x.Transparency < 1 and x ~= TERRAIN then f = true break end
		end
		probe.Parent = nil
		return f
	end
	local eps = 0.06
	-- a spot along the edge line counts if: it's still an inside corner the same way round, the WALL the fill leans
	-- on is still there (v2.40: it used to run on past the end of a wall / round a pillar's outside corner), and the
	-- spot where the fill would go is still EMPTY (it used to run straight through a pillar standing in the corner)
	local function test(t)
		local u = ENT.edgeInside(E, p, t)
		if not u or (u0 and u:Dot(u0) <= 0.99) then return false end
		if u0 and v0 then
			local m = cf:PointToWorldSpace(edgeC + AXV[E.k] * t)
			if not solidAny(m - u0 * eps + v0 * eps) then return false end
			if r then
				local z = m + (u0 + v0) * (r * 0.3)
				-- something solid where the fill goes = stop (a pillar) - unless it's just another FILL (they meet
				-- and get mitred; stopping short there left a notch in 3-way corners)
				if solidAny(z) and not ENT.inFill(z) then return false end
			end
		end
		return true
	end
	local ok = {}
	for i = 0, N do
		local t = -hk + step * i
		ok[i] = test(math.clamp(t, -hk + step * 0.25, hk - step * 0.25))
	end
	local lp = cf:PointToObjectSpace(hitPos)
	local tc = ({ lp.X, lp.Y, lp.Z })[E.k]
	local ic = math.clamp(math.floor((tc + hk) / step + 0.5), 0, N)
	if not ok[ic] then
		local best
		for i = 0, N do if ok[i] and (not best or math.abs(i - ic) < math.abs(best - ic)) then best = i end end
		if not best then probe:Destroy() return -hk, hk end
		ic = best
	end
	local i0, i1 = ic, ic
	while i0 > 0 and ok[i0 - 1] do i0 -= 1 end
	while i1 < N and ok[i1 + 1] do i1 += 1 end
	-- the exact spot where it stops = halve the gap between the last good spot and the first bad one
	local function refine(good, bad)
		for _ = 1, 10 do
			local m = (good + bad) / 2
			if test(m) then good = m else bad = m end
		end
		return good
	end
	-- past the ends of THIS block the corner can carry on along the next block - walk out until it stops
	local function walkOut(sign)
		local good = sign * hk
		for _ = 1, 400 do
			local nxt = good + sign * step
			if math.abs(nxt) > hk + 400 then break end
			if test(nxt) then good = nxt else return refine(good, nxt) end
		end
		return good
	end
	local from = (i0 == 0) and walkOut(-1) or refine(-hk + step * i0, -hk + step * (i0 - 1))
	local to = (i1 == N) and walkOut(1) or refine(-hk + step * i1, -hk + step * (i1 + 1))
	-- v2.40 (Dylan: "build it, then cut"): where the fill is stopped by something SOLID (a wall, a pillar, another
	-- fill), it's built r further, INTO that thing - the extra is hidden inside it, and the corner can't be left
	-- with a gap. Where it stops at open air it ends right there.
	local function blocked(t, sign)
		if not (u0 and v0 and r) then return false end
		local m = cf:PointToWorldSpace(edgeC + AXV[E.k] * (t + sign * 0.1))
		return solidAny(m + (u0 + v0) * (r * 0.3)) or solidAny(m + u0 * (r * 0.15) + v0 * (r * 0.15))
	end
	-- an end within a hair of THIS block's own end = exactly its end (no tiny lip past the wall)
	if math.abs(from + hk) < 0.05 then from = -hk end
	if math.abs(to - hk) < 0.05 then to = hk end
	-- ends: against something SOLID (a wall) = a hair (0.02) into it to seal it; at OPEN AIR = exactly at the edge
	-- (v2.40: the hair at open ends showed as a tiny overshoot)
	if blocked(from, -1) then from -= 0.02 end
	if blocked(to, 1) then to += 0.02 end
	probe:Destroy()
	return from, to
end
function ENT.edgeStart(kind)
	if sk then exitSketch() end
	if mode ~= "planes" then setMode("planes") end
	if ENT.shellTool then ENT.shellStop() end
	ENT.edgeTool = kind
	if ENT.eSelClear then pcall(ENT.eSelClear, true) end
	setStatus((kind == "fillet" and "ROUND" or "CHAMFER") .. ": set the Size (PROPERTIES), then CLICK an edge - it's done straight away (green = the edge under the mouse). Click more edges to add more. Ctrl+Z undoes one. Esc = stop.")
	if ENT.ribPaint then pcall(ENT.ribPaint) end
end
function ENT.edgeStop()
	if ENT.eSelClear then pcall(ENT.eSelClear, true) end   -- v3.50
	ENT.edgeTool = nil
	ENT.edgeLine.Visible = false
	if ENT.drawTopoEdge then pcall(ENT.drawTopoEdge, nil) end
	ENT.topoHot = nil
	dimTag.Enabled = false
	if ENT.ribPaint then pcall(ENT.ribPaint) end
	refreshStatus()
end
function ENT.edgeHover()
	local hit = ENT.directHit()
	-- v2.76 REAL EDGES first: on a PROTO part, any edge of its real shape (the whole edge lights up)
	ENT.topoHot = nil
	do
		local cands = {}
		if hit and hit.Instance then cands[#cands + 1] = hit.Instance end
		if target and target:IsA("BasePart") and target ~= (hit and hit.Instance) then cands[#cands + 1] = target end
		for _, cand in ipairs(cands) do
			if cand:IsA("BasePart") and ENT.detailKind(cand) then
				local T = ENT.partTopo(cand)
				local E = T and ENT.edgePickScreen(T)   -- v3.50: in screen pixels, hidden edges skipped
				-- v3.31 (Dylan: "the outside of a box should be green - supported"): a block's own box edges go the SAME
				-- way as every other edge now (a step in the recipe: corners meet properly, no horn where the old way and
				-- the new way met). Only an inside corner where ANOTHER part wraps round this block keeps the old way
				-- (it can fill between the two parts and join them).
				if E and ENT.isBoxEdge(cand, E) then
					local BE = hit and hit.Instance == cand and ENT.edgeAt(cand, hit.Position)
					if BE then
						local key = tostring(cand) .. BE.k .. BE.sa .. BE.sb .. tostring(cand.CFrame) .. tostring(cand.Size)
						local c = ENT.boxInCache
						if not (c and c.key == key) then
							local okI, u = pcall(ENT.edgeInside, BE, cand)
							c = { key = key, inside = okI and u ~= nil }
							ENT.boxInCache = c
						end
						if c.inside then E = nil end
					end
				end
				if E then
					ENT.topoHot = { p = cand, E = E }
					ENT.drawTopoEdge(E)
					ENT.edgeLine.Visible = false
					local r = ENT.filletSize() or 0
					local mid = E.pts[math.max(1, math.floor(#E.pts / 2))]
					dimTag.StudsOffsetWorldSpace = mid
					dimTag.T.Text = (ENT.edgeTool == "fillet" and "ROUND r " or "CHAMFER ") .. fmt(r) .. (E.convex and "" or "  (inside edge: fills)") .. (E.closed and "  - all the way round" or "")
					dimTag.Enabled = true
					return
				end
			end
		end
		ENT.drawTopoEdge(nil)
	end
	-- v2.40 POCKET EDGES first (looking into a cut)
	ENT.pocketHot = nil
	-- (from INSIDE a cut the mouse ray may not hit the part at all - then the picked part's cuts are checked)
	-- (v2.40, Dylan: "when I'm inside the cut the mouse grabs the inside of the cube I'm in"): from inside the part the
	-- mouse ray skips it and lands on whatever is behind - so the part under the mouse AND the picked part (and the
	-- part the camera is inside) are all tried
	local okE, PE, pRoot = false, nil, nil
	local tries = {}
	if hit and hit.Instance then tries[#tries + 1] = hit.Instance end
	if target and target:IsA("BasePart") then tries[#tries + 1] = target end
	if ENT.lastPocketPart and ENT.lastPocketPart.Parent then tries[#tries + 1] = ENT.lastPocketPart end
	for _, cand in ipairs(tries) do
		if cand:IsA("BasePart") and ENT.isProto(cand) then
			local okT, PT = pcall(ENT.pocketEdgePick, mouse.UnitRay, cand)
			if not okT then print("PROTO pocket hover error: " .. tostring(PT)) end
			if okT and PT then okE, PE, pRoot = true, PT, cand break end
		end
	end
	if pRoot then
		ENT.lastPocketPart = pRoot
		if okE and PE then
			ENT.pocketHot = { E = PE, p = pRoot }
			local now = os.clock()
			if not ENT.lastPocketLog or now - ENT.lastPocketLog > 1.5 then
				ENT.lastPocketLog = now
				local la, lb = pRoot.CFrame:PointToObjectSpace(PE.a), pRoot.CFrame:PointToObjectSpace(PE.b)
				local lc = pRoot.CFrame:PointToObjectSpace(PE.box.ctr)
				print(("PROTO pocket hover: %s edge %.2f,%.2f,%.2f -> %.2f,%.2f,%.2f | box centre %.2f,%.2f,%.2f size %.2f x %.2f x %.2f")
					:format(PE.kind, la.X, la.Y, la.Z, lb.X, lb.Y, lb.Z, lc.X, lc.Y, lc.Z, PE.box.half[1] * 2, PE.box.half[2] * 2, PE.box.half[3] * 2))
			end
			local r = ENT.filletSize() or 0
			ENT.edgeLine.CFrame = CFrame.lookAt(PE.a, PE.b)
			ENT.edgeLine.Length = (PE.b - PE.a).Magnitude
			ENT.edgeLine.Visible = true
			ENT.edgeLine.Color3 = (PE.kind == "in") and Color3.fromRGB(160, 255, 200) or Color3.fromRGB(80, 230, 120)
			dimTag.StudsOffsetWorldSpace = (PE.a + PE.b) / 2
			dimTag.T.Text = (ENT.edgeTool == "fillet" and "FILLET r " or "CHAMFER ") .. fmt(r) .. ((PE.kind == "in") and "  (inside the cut: fills)" or "  (edge of the opening)")
			dimTag.Enabled = true
			return
		end
	end
	local E = hit and ENT.edgeAt(hit.Instance, hit.Position)
	if not E then
		ENT.edgeLine.Visible = false
		dimTag.Enabled = false
		return
	end
	local a, b = ENT.edgeWorld(E)
	local r = ENT.filletSize() or 0
	local inside, iv, nbp = ENT.edgeInside(E, hit.Instance)
	-- v2.40: an inside corner shows where the fill will REALLY go (it can carry on past this block / stop at a
	-- pillar), not just this block's edge. Worked out once per edge (it's a few probes), then remembered.
	if inside and r > 0 then
		local key = tostring(hit.Instance) .. E.k .. E.sa .. E.sb .. r
		local c = ENT.spanCache
		if not (c and c.key == key) then
			local ok, s0, s1 = pcall(ENT.insideSpan, E, hit.Instance, hit.Position, inside, iv, r)
			c = { key = key, s0 = ok and s0 or nil, s1 = ok and s1 or nil }
			ENT.spanCache = c
		end
		if c.s0 then
			local eC = AXV[E.a] * (E.sa * E.h[E.a]) + AXV[E.b] * (E.sb * E.h[E.b])
			a, b = E.cf:PointToWorldSpace(eC + AXV[E.k] * c.s0), E.cf:PointToWorldSpace(eC + AXV[E.k] * c.s1)
		end
	end
	ENT.edgeLine.CFrame = CFrame.lookAt(a, b)
	ENT.edgeLine.Length = (b - a).Magnitude
	ENT.edgeLine.Visible = true
	dimTag.StudsOffsetWorldSpace = (a + b) / 2
	ENT.edgeLine.Color3 = inside and Color3.fromRGB(160, 255, 200) or Color3.fromRGB(80, 230, 120)
	dimTag.T.Text = (ENT.edgeTool == "fillet" and "FILLET r " or "CHAMFER ") .. fmt(r) .. (inside and (ENT.edgeJoin and nbp and "  (inside: fills + JOINS)" or "  (inside corner: fills)") or "")
	dimTag.Enabled = true
end
-- is there an inside fill running along axis kf, sitting at the 'endAx' end with sign endSign, at level sign lvSign on axis kc?
function ENT.otherBand(done, kf, endAx, endSign, kc, lvSign)
	for _, d in ipairs(done or {}) do
		if d.i and d.ux and d.k == kf then
			local ad, bd = (kf % 3) + 1, ((kf + 1) % 3) + 1
			local sg = { 0, 0, 0 }
			sg[ad], sg[bd] = d.a, d.b
			if sg[endAx] == endSign and sg[kc] == lvSign then return true end
		end
	end
	return false
end
-- ===== v2.40 POCKET EDGES (Dylan: "fillets on the inside of the cut, using the faces"). The edges of a cut's pocket
-- box: where two of its walls / its floor meet = an INSIDE corner (the fillet / chamfer ADDS a fill), where a wall
-- meets the open side (the rim of the opening) = an OUTSIDE edge (it's rounded / cut off). =====
function ENT.pocketBoxes(root)
	local out = {}
	if not root then return out end
	local parts = ENT.objParts(root) or { root }
	ENT.prismCache = ENT.prismCache or {}
	ENT.outlineCache = ENT.outlineCache or {}
	for _, q in ipairs(parts) do
		if q:IsA("BasePart") then
			for _, ch in ipairs(q:GetChildren()) do
				if ENT.isOutline(ch.Name) and ch:IsA("StringValue") and ENT.outKind(ch, q) == "cut" then
					local P = ENT.prismCache[ch.Value]
					if P == nil then
						local data = ENT.outlineCache[ch.Value]
						if not data then
							local okD, r = pcall(function() return game:GetService("HttpService"):JSONDecode(ch.Value) end)
							data = okD and r or {}
							ENT.outlineCache[ch.Value] = data
						end
						P = ENT.cutPrism(data) or false
						ENT.prismCache[ch.Value] = P
					end
					if P and #P.ring == 4 then
						pcall(function()
							local bcf, bsz = ENT.blockOf(q)
							if not bcf then bcf, bsz = q.CFrame, q.Size end
							local segs = ENT.pocketSegs(P, q.CFrame, bcf, bsz)
							if #segs < 3 then return end
							local d = q.CFrame:VectorToWorldSpace(P.D).Unit
							local e1 = q.CFrame:VectorToWorldSpace(P.ring[1].b - P.ring[1].a).Unit
							if math.abs(e1:Dot(d)) > 0.01 then return end
							local e2 = d:Cross(e1).Unit
							local ax = { e1, e2, d }
							local lo, hi = { math.huge, math.huge, math.huge }, { -math.huge, -math.huge, -math.huge }
							local o0 = segs[1][1]
							for _, sg in ipairs(segs) do
								for _, w in ipairs({ sg[1], sg[2] }) do
									for i = 1, 3 do
										local x = (w - o0):Dot(ax[i])
										lo[i], hi[i] = math.min(lo[i], x), math.max(hi[i], x)
									end
								end
							end
							local half = { (hi[1] - lo[1]) / 2, (hi[2] - lo[2]) / 2, (hi[3] - lo[3]) / 2 }
							-- (v2.40: the real cut is a hair WIDER than its saved outline - the cutter grows so it never leaves a skin)
								-- v2.40: exact = the REAL cutter's corners (saved at cut time), clipped to the part's box
							local exact = false
							local tj = ch:GetAttribute("DIM_tool")
							if type(tj) == "string" then
								local okT, tp = pcall(function() return game:GetService("HttpService"):JSONDecode(tj) end)
								if okT and type(tp) == "table" and #tp >= 8 then
									local tlo, thi = { math.huge, math.huge, math.huge }, { -math.huge, -math.huge, -math.huge }
									for _, t3 in ipairs(tp) do
										local w = q.CFrame:PointToWorldSpace(V3(t3[1], t3[2], t3[3]))
										for i = 1, 3 do local x = (w - o0):Dot(ax[i]) tlo[i], thi[i] = math.min(tlo[i], x), math.max(thi[i], x) end
									end
									local ph = bsz / 2
									local plo, phi = { math.huge, math.huge, math.huge }, { -math.huge, -math.huge, -math.huge }
									for _, sx in ipairs({ -1, 1 }) do for _, sy in ipairs({ -1, 1 }) do for _, sz in ipairs({ -1, 1 }) do
										local w = (bcf * CFrame.new(ph.X * sx, ph.Y * sy, ph.Z * sz)).Position
										for i = 1, 3 do local x = (w - o0):Dot(ax[i]) plo[i], phi[i] = math.min(plo[i], x), math.max(phi[i], x) end
									end end end
									local ok3 = true
									local nlo, nhi = {}, {}
									for i = 1, 3 do nlo[i], nhi[i] = math.max(tlo[i], plo[i]), math.min(thi[i], phi[i]) if nhi[i] - nlo[i] < 0.04 then ok3 = false end end
									if ok3 then
										lo, hi = nlo, nhi
										half = { (hi[1] - lo[1]) / 2, (hi[2] - lo[2]) / 2, (hi[3] - lo[3]) / 2 }
										exact = true
									end
								end
							end
							if not exact then
								local gw = ENT.cutGrowOf(ch, q) half[1], half[2] = half[1] + gw, half[2] + gw
							end
							if half[1] < 0.02 or half[2] < 0.02 or half[3] < 0.02 then return end
							-- v2.70: a "pocket" as big as the whole block isn't a pocket (its edges are the block's own)
							do
								local big = 0
								for i = 1, 3 do
									local ext = 0
									for _, bax in ipairs({ bcf.XVector * bsz.X, bcf.YVector * bsz.Y, bcf.ZVector * bsz.Z }) do ext += math.abs(bax:Dot(ax[i])) end
									if half[i] * 2 >= ext - 0.12 then big += 1 end
								end
								if big >= 3 then return end
							end
							local ctr = o0 + e1 * ((lo[1] + hi[1]) / 2) + e2 * ((lo[2] + hi[2]) / 2) + d * ((lo[3] + hi[3]) / 2)
							local bh = { bsz.X / 2, bsz.Y / 2, bsz.Z / 2 }
							local open = { {}, {}, {} }
							for i = 1, 3 do
								for _, s in ipairs({ -1, 1 }) do
									local fc = ctr + ax[i] * (half[i] * s)
									local lc = bcf:PointToObjectSpace(fc)
									local la = bcf:VectorToObjectSpace(ax[i])
									local L, A = { lc.X, lc.Y, lc.Z }, { la.X, la.Y, la.Z }
									local o = false
									for m = 1, 3 do
										if math.abs(A[m]) > 0.99 and math.abs(L[m]) >= bh[m] - 0.03 then o = true end
									end
									open[i][s] = o
								end
							end
							out[#out + 1] = { part = q, ctr = ctr, ax = ax, half = half, open = open }
							if ENT.pocketLogNext then
								ENT.pocketLogNext = nil
								local lc = q.CFrame:PointToObjectSpace(ctr)
								print(("PROTO pocket box: %s | centre (part) %.3f, %.3f, %.3f | size %.3f x %.3f x %.3f | from the cutter's corners: %s")
									:format(q.Name, lc.X, lc.Y, lc.Z, half[1] * 2, half[2] * 2, half[3] * 2, tostring(exact)))
							end
						end)
					end
				end
			end
		end
	end
	return out
end
-- every edge of every pocket box (world): { a, b, kind = "in" / "rim", u, v (the fill / cutter opens along these), box }
function ENT.pocketEdges(root)
	local list = {}
	for _, B in ipairs(ENT.pocketBoxes(root)) do
		local ax, half = B.ax, B.half
		for i = 1, 3 do
			for j = i + 1, 3 do
				local k = 6 - i - j
				for _, s1 in ipairs({ -1, 1 }) do
					for _, s2 in ipairs({ -1, 1 }) do
						local oi, oj = B.open[i][s1], B.open[j][s2]
						if not (oi and oj) then
							local base = B.ctr + ax[i] * (half[i] * s1) + ax[j] * (half[j] * s2)
							local outI, outJ = -ax[i] * s1, -ax[j] * s2   -- (into the pocket from each face)
							local E = { a = base - ax[k] * half[k], b = base + ax[k] * half[k], box = B, dir = ax[k] }
							if not oi and not oj then
								E.kind, E.u, E.v = "in", outI, outJ
							elseif oi then
								E.kind, E.u, E.v = "rim", outI, -outJ
								E.depth, E.wall = outI, -outJ   -- (in from the open face / into the wall's material)
							else
								E.kind, E.u, E.v = "rim", -outI, outJ
								E.depth, E.wall = outJ, -outI
							end
							list[#list + 1] = E
						end
					end
				end
			end
		end
	end
	return list
end
-- can the camera see this point through the pocket's open side(s)? (not through solid wall)
function ENT.pocketSeen(B, ray, t)
	local ax, half = B.ax, B.half
	-- (v2.40: the camera is INSIDE the cut = it can see every edge of it)
	local o = ray.Origin - B.ctr
	if math.abs(o:Dot(ax[1])) <= half[1] + 0.05 and math.abs(o:Dot(ax[2])) <= half[2] + 0.05 and math.abs(o:Dot(ax[3])) <= half[3] + 0.05 then return true end
	for i = 1, 3 do
		for _, s in ipairs({ -1, 1 }) do
			if B.open[i][s] then
				local j, l = (i % 3) + 1, ((i + 1) % 3) + 1
				local pl = planeFrom(B.ctr + ax[i] * (half[i] * s), ax[j], ax[l])
				local t2, h2 = rayPlane(pl, ray)
				if t2 and t2 <= t + 0.05 then
					local l2 = to2D(pl, h2)
					if math.abs(l2.X) <= half[j] + 0.05 and math.abs(l2.Y) <= half[l] + 0.05 then return true end
				end
			end
		end
	end
	return false
end
-- the pocket edge nearest the mouse ray (that the camera can really see)
function ENT.pocketEdgePick(ray, root)
	local best, bd
	for _, E in ipairs(ENT.pocketEdges(root)) do
		-- closest points between the ray and the edge
		local d1, d2 = ray.Direction, E.b - E.a
		local r0 = ray.Origin - E.a
		local a, b, c = d1:Dot(d1), d1:Dot(d2), d2:Dot(d2)
		local dd, e = d1:Dot(r0), d2:Dot(r0)
		local den = a * c - b * b
		if den > 1e-9 then
			local tr = (b * e - c * dd) / den
			local te = math.clamp((a * e - b * dd) / den, 0, 1)
			local pe = E.a + d2 * te
			tr = math.max(0, (pe - ray.Origin):Dot(d1) / a)
			local pr = ray.Origin + d1 * tr
			local dist = (pr - pe).Magnitude
			local tol = math.max(0.4, tr * 0.04)   -- (v2.40: as easy to grab as the outside edges)
			if dist < tol and (not bd or dist < bd) and ENT.pocketSeen(E.box, ray, tr) then best, bd = E, dist end
		end
	end
	return best
end
function ENT.pocketEdgeKey(p, E)
	-- (v2.40: measured in the BLOCK's own space - the part's own centre moves a hair after each cut / fill, which made
	-- done edges look not-done = done twice)
	local bcf = ENT.blockOf(p) or p.CFrame
	local m = bcf:PointToObjectSpace((E.a + E.b) / 2)
	return string.format("%.1f,%.1f,%.1f", m.X, m.Y, m.Z)
end
-- fillet / chamfer a pocket edge: inside corner = a fill added, rim = rounded / cut off
function ENT.pocketEdgeClick(E, p)
	if not ENT.meshGate() then return end
	-- v2.69: one at a time (clicking again while it's still rebuilding started 10 rebuilds in a second)
	if ENT.rebuildBusy then setStatus("Still working on the last one - one moment.") return end
	ENT.pocketLogNext = true
	ENT.pocketBoxes(p)
	local isF = ENT.edgeTool == "fillet"
	local nm = isF and "FILLET" or "CHAMFER"
	local r = ENT.filletSize()
	if not r or r <= 0 or r ~= r then setStatus(nm .. ": type a size above 0 in the 'size' box.") return end
	local L = (E.b - E.a).Magnitude
	local bh = E.box.half
	local room = math.huge
	for i = 1, 3 do if math.abs(E.box.ax[i]:Dot(E.dir)) < 0.5 then room = math.min(room, bh[i] * 2) end end
	if E.kind == "in" and r > room - 1e-3 then setStatus(nm .. ": too big for this pocket (" .. fmt(room) .. " studs across).") return end
	local doneList = {}
	pcall(function() doneList = HttpService:JSONDecode(p:GetAttribute("PROTO_PocketEdges") or "[]") end)
	local key = ENT.pocketEdgeKey(p, E)
	-- (entries: "x,y,z|r|f/c" - older ones are just "x,y,z")
	local function doneAt(k0)
		for _, k in ipairs(doneList) do
			local kk, rr, tt = string.match(k, "^([^|]+)|?([^|]*)|?([^|]*)$")
			if kk == k0 then return true, tonumber(rr), tt end
		end
		return false
	end
	if doneAt(key) then setStatus(nm .. ": that edge is already done. Ctrl+Z to change it.") return end
	-- v2.57 MESH-ONLY: a block PROTO rebuilt (it has a recipe) = the round / chamfer goes into that cut's own cutter and
	-- the block is rebuilt in one go; otherwise an opening's edge = ONE cutter round the whole opening, ONE cut; an
	-- inside edge of an old cut can't be done without joining, so it says so. (The old picture-frame pieces are gone.)
	if ENT.rebuildable(p) and #ENT.cutsOf(p) > 0 then
		if ENT.pocketRecipeEdge(E, p, r, isF) then return end
		-- v2.70: not one of its cuts' edges - let the block edge tool have the click (no Roblox cut for recipe blocks)
		return false
	end
	if E.kind == "rim" then
		-- v3.41 (glitch sweep): mark busy so a second click can't start a second rebuild at the same time
		ENT.rebuildBusy = true
		local okR, doneR = pcall(ENT.pocketRimMesh, E, p, r, isF)
		ENT.rebuildBusy = false
		if okR and doneR then return end
		if not okR then warn("PROTO " .. nm .. ": " .. tostring(doneR)) end
		setStatus(nm .. ": couldn't do that opening edge.")
		return
	end
	setStatus(nm .. ": this cut was made before PROTO remembered its cuts, so rounding its inside would mean joining a piece on (PROTO doesn't). Ctrl+Z the cut and cut it again, then round it.")
end
-- v3.57 (Dylan: "just make it click to add, that's it"): click an edge = it's chamfered / rounded straight away at the
-- Size in PROPERTIES (no picking, no live preview, no Enter). The screen-pixel edge finding (v3.50) stays.
-- (false = the v3.50 pick + live preview + Enter way again.)
ENT.EDGE_OLD = true
function ENT.edgeClick()
	if not ENT.meshGate() then return end
	if ENT.rebuildBusy then setStatus("Still working on the last one - one moment.") return end
	-- v2.76: a real edge of a PROTO part (lit up by edgeHover)
	if ENT.topoHot and ENT.topoHot.p and ENT.topoHot.p.Parent and not ENT.EDGE_OLD then
		-- v3.50: pick first (orange), size live, Enter = make them all
		local H = ENT.topoHot
		ENT.eSelToggle(H.p, H.E)
		return
	end
	if ENT.topoHot and ENT.topoHot.p and ENT.topoHot.p.Parent then
		local H = ENT.topoHot
		ENT.topoHot = nil
		local isF = ENT.edgeTool == "fillet"
		local nm = isF and "ROUND" or "CHAMFER"
		local r = ENT.filletSize()
		if not r or r <= 0 or r ~= r then setStatus(nm .. ": type a size above 0 in the 'size' box.") return end
		ENT.rebuildBusy = true
		setStatus(nm .. ": rebuilding the part with it...")
		local ok, np, why = pcall(ENT.edgeStep, H.p, H.E, r, isF)
		ENT.rebuildBusy = false
		ENT.drawTopoEdge(nil)
		if ok and np then
			setStatus(nm .. " done (" .. fmt(r) .. ") - it's a step in the part's recipe (STEPS on the right: change it or take it out). Ctrl+Z undoes it."
				.. (ENT.lastEdgeMoved and (" It went in before the " .. ENT.lastEdgeMoved .. " round(s) / chamfer(s) it runs into, so they follow round it.") or ""))
		else
			setStatus(nm .. ": " .. tostring(ok and why or np))
			warn("PROTO " .. nm .. ": " .. tostring(ok and why or np))
		end
		pcall(ENT.edgeHover)
		return
	end
	ENT.newWraps = nil
	ENT.edgeSave = nil
	local hit = ENT.directHit()
	-- v2.40: an edge of a cut's pocket under the mouse comes first
	if ENT.pocketHot and ENT.pocketHot.p and ENT.pocketHot.p.Parent then
		local H = ENT.pocketHot
		ENT.pocketHot = nil
		if ENT.pocketEdgeClick(H.E, H.p) ~= false then
			ENT.edgeHover()
			return
		end
	end
	if not hit then return end
	local p = hit.Instance
	local E = ENT.edgeAt(p, hit.Position)
	local nm = (ENT.edgeTool == "fillet") and "FILLET" or "CHAMFER"
	if not E then
		if ENT.blockOf(p) then setStatus(nm .. ": click closer to an edge (it lights up green).")
		else setStatus(nm .. ": hover an edge until it lights up green, then click. Works on blocks, cylinders and anything PROTO built - not on wedges, balls or meshes PROTO didn't make.") end
		return
	end
	local r = ENT.filletSize()
	if not r or r <= 0 or r ~= r then setStatus(nm .. ": type a size above 0 in the 'size' box.") return end
	if r > math.min(E.size[({ "X", "Y", "Z" })[E.a]], E.size[({ "X", "Y", "Z" })[E.b]]) - 1e-3 then
		setStatus(nm .. ": too big - the faces beside that edge are only " .. fmt(math.min(E.size[({ "X", "Y", "Z" })[E.a]], E.size[({ "X", "Y", "Z" })[E.b]])) .. " studs.")
		return
	end
	local isF = ENT.edgeTool == "fillet"
	-- v2.40 (Dylan): clicking an edge that's ALREADY done does nothing (a second click re-cut it and undid the wrap)
	do
		local done0 = {}
		pcall(function() done0 = HttpService:JSONDecode(p:GetAttribute("PROTO_EdgesDone") or "[]") end)
		for _, d in ipairs(done0) do
			if d.t and d.k == E.k and d.a == E.sa and d.b == E.sb then
				setStatus(nm .. ": that edge is already done (" .. d.t .. " " .. fmt(d.r or 0) .. "). Ctrl+Z to change it.")
				return
			end
		end
	end
	-- v2.52 MESH MODE: the block + all its edges are rebuilt as ONE piece (no pieces, no joining) - ENT.edgeMesh
	-- v2.57 MESH-ONLY: the ONLY way (the old piece-by-piece edge code is gone)
	ENT.rebuildBusy = true
	local okE, errE = pcall(ENT.edgeMesh, p, E, r, isF, hit.Position)
	ENT.rebuildBusy = false
	if not okE then warn("PROTO: " .. tostring(errE)) setStatus("Error: " .. tostring(errE)) end
end
-- v2.38: the real part face under the mouse - no planes, panels or invisible boxes in the way
function ENT.directHit()
	local ray = mouse.UnitRay
	local params = RaycastParams.new()
	params.FilterType = Enum.RaycastFilterType.Exclude
	local skip = {}
	for _ = 1, 8 do
		params.FilterDescendantsInstances = skip
		local res = workspace:Raycast(ray.Origin, ray.Direction * 5000, params)
		if not res then return nil end
		local q = res.Instance
		if q == TERRAIN or q.Locked or ENT.isBox(q.Name) or ENT.isPrev(q.Name) or not q:IsA("BasePart") then
			table.insert(skip, q)
		else
			return res
		end
	end
	return nil
end
-- ===== face mode =====
local AXIS = {
	[Enum.NormalId.Right] = V3(1, 0, 0), [Enum.NormalId.Left] = V3(-1, 0, 0),
	[Enum.NormalId.Top] = V3(0, 1, 0), [Enum.NormalId.Bottom] = V3(0, -1, 0),
	[Enum.NormalId.Back] = V3(0, 0, 1), [Enum.NormalId.Front] = V3(0, 0, -1),
}
function ENT.faceOk(p, f)
	if not p or not p:IsA("BasePart") or p == TERRAIN or p.Locked then return false, "not a part" end
	if p:IsA("Part") then
		if p.Shape == Enum.PartType.Ball then return false, "balls can't be extruded" end
		if p.Shape == Enum.PartType.Cylinder and f ~= Enum.NormalId.Right and f ~= Enum.NormalId.Left then
			return false, "cylinders: only the flat ends extrude"
		end
	end
	return true
end
function ENT.faceApply(p, f, size0, cf0, d)
	local n = AXIS[f]
	local axis = V3(math.abs(n.X), math.abs(n.Y), math.abs(n.Z))
	local len0 = size0:Dot(axis)
	if len0 + d < 0.05 then d = 0.05 - len0 end
	p.Size = size0 + axis * d
	p.CFrame = cf0 * CFrame.new(n * (d / 2))
end
function faceUnlock()
	if dragStart then   -- v2.36: unlocked mid-drag - close the undo step so it isn't left open
		if dragStart.rec then pcall(function() CHS:FinishRecording(dragStart.rec, Enum.FinishRecordingOperation.Commit) end) end
		dragStart = nil
	end
	facePart, faceId = nil, nil
	faceLock.Adornee = nil
	handles.Adornee = nil
end
function ENT.faceLockOn(p, f)
	local ok, why = ENT.faceOk(p, f)
	if not ok then setStatus("FACE: " .. why) return end
	facePart, faceId = p, f
	faceLock.Adornee = p
	faceLock.TargetSurface = f
	handles.Adornee = p
	handles.Faces = Faces.new(f)
	Selection:Set({ p })
	refreshStatus()
end
function faceNudge(sign)
	if not facePart or not facePart.Parent then setStatus("Face mode: click a face first.") return end
	local amt = tonumber(U.faceAmt.Text)
	if not amt then setStatus("Amount must be a number.") return end
	record("PROTO Face extrude", function() ENT.faceApply(facePart, faceId, facePart.Size, facePart.CFrame, sign * amt) end)
end
handles.MouseEnter:Connect(function() overHandle = true end)
handles.MouseLeave:Connect(function() overHandle = false end)
handles.MouseButton1Down:Connect(function()
	if not facePart then return end
	local id
	pcall(function() id = CHS:TryBeginRecording("PROTO Face drag") end)
	dragStart = { size = facePart.Size, cf = facePart.CFrame, rec = id }
end)
handles.MouseDrag:Connect(function(_, distance)
	if not facePart or not dragStart then return end
	local g = ctrlDown() and 0 or gridSize()
	local d = g > 0 and math.floor(distance / g + 0.5) * g or distance
	ENT.faceApply(facePart, faceId, dragStart.size, dragStart.cf, d)
	setStatus(("FACE: %s / %s   %+.3f"):format(facePart.Name, faceId.Name, d))
end)
handles.MouseButton1Up:Connect(function()
	if dragStart then
		if dragStart.rec then CHS:FinishRecording(dragStart.rec, Enum.FinishRecordingOperation.Commit) else CHS:SetWaypoint("PROTO Face drag") end
	end
	dragStart = nil
	refreshStatus()
end)

